#!/usr/bin/env node
/**
 * suite-power.js —— 【第 64 轮·删除合并】省电与发热门控
 * 成员 2 个：sim-power-drain.js、sim-heat-idle-gates.js
 *
 * 本文件由「成员源码原样嵌入」生成：每个成员在套件里仍然是**它自己那份源码**，
 * 跑在独立的作用域里（自己的 require / process / console / __dirname / __filename /
 * module / exports），彼此不共享变量；成员的 `process.exit(c)` 由套件记录退出码
 *（不真的退出 —— 与 run.py 的 runner 同一种 shim，行为逐字等价）。
 *
 * 为什么合并：scripts/ 里躺着上百个两三千字节的独立脚本，用户第 64 轮明确要求
 * 「删除合并 scripts 文件夹中的脚本文件」；套件把同主题的契约收进一个文件，
 * 覆盖率一个成员都不少（合并前逐文件 __EXIT__ 与合并后逐成员 exit 已逐项比对）。
 *
 * 注意：scripts/ 不参与打包（不进 App bundle），所以这一步**不省电、不降温** ——
 * 省电的改动都在 src/ 与 ios/ 里（见改动清单第六十四轮）。
 *
 * 运行：python "C:\Users\Q\AppData\Local\Temp\lx-jsrun\run.py" scripts/suite-power.js --brief
 *   `--brief` 只看 FAIL / ===== / 结果 行；去掉 `--brief` 看每个成员的全部输出。
 * 也可以用真实 node 跑（`node scripts/suite-power.js`、`npm run lint:sound-effect-dsp`）：
 * 成员一律用 path.resolve(__dirname, '..') 定位工程根，套件把**自己的** __dirname
 * 传下去，所以两种环境下指向同一棵树。
 * 退出码：全部成员 exit 0 时为 0，否则为第一个非 0 的成员退出码。
 */
'use strict'

const THEME = "省电与发热门控"

const MEMBERS = [
  { n: "sim-power-drain.js", s: "/**\n * sim-power-drain.js\n *\n * 「后台播放耗电」契约不变量。\n *\n * 背景：有用户反馈「只播放 1 小时就掉 10% 电」。逐层排查后，前台（屏幕亮着）的\n * 耗电主要来自几处 rAF 每帧循环（歌词连续滚动、逐字卡拉OK 插值、lrc 解析器\n * ticker）——这些在 iOS 后台会被系统暂停（rAF 由 CADisplayLink 驱动，无显示时\n * 停摆），不构成后台耗电。真正在**后台（锁屏 / 揣兜里）持续唤醒 CPU** 的是：\n *\n *   ① 原生 GCD 歌词时钟（AppDelegate.mm 的 LXNowPlayingLyricStep），周期 0.12s\n *      = 8.3Hz，**一经创建永不停止**：即使暂停 / 停止 / 清空歌词 / 切到无歌词的\n *      歌，它仍按 8.3Hz 起床做二分查找（虽多数分支早退，但 8.3Hz 的唤醒本身就是\n *      耗电，且锁屏时 CPU 本应深度睡眠）。\n *   ② JS BackgroundTimer 轮询（playProgress.ts 的 1s 慢校准 tick）：其原生实现\n *      （RNBackgroundTimer.m）每个 setTimeout/setInterval 都调\n *      `beginBackgroundTaskWithName:` 申请后台任务断言——这对系统是重操作，\n *      且让 App 保持「可运行」而不被挂起。后台 body 虽被 AppState 守卫早退，\n *      但定时器本身每秒仍在申请/释放断言。\n *   ③ 热路径 NSLog（LXNowPlayingLyricStep 每次换行、setNowPlayingLyrics 每次设行）\n *      ——NSLog 是同步写 Apple System Log，锁屏期间每次换行都唤醒 I/O。\n *\n * 本脚本把这些绑成不变量，并带反例自检（tsc/eslint 对「定时器未停」「日志未删」\n * 完全无感）。运行：node scripts/sim-power-drain.js\n * 退出码：不变量全过、且全部反例被拦下时为 0，否则 1。\n *\n * 第 4 段（2026-10-02 用户第 8 条）「后台不可见即停」：背景播放让进程锁屏后常驻，\n * 于是三类**只有前台才需要**的工作会跟着跑一整夜 —— 液态玻璃 MTKView 连续渲染\n * （Tab 栏 2 块 + 迷你播放器 1 块）、播放详情页的缓冲进度轮询（每秒一次原生桥往返\n * + setState）、RNFS 下载进度的逐数据块回调（每次串起 store 事件 + React 渲染）。\n * 共同口径：前台才做，退后台立即停，回前台再恢复。绑住：4 条不变量 + 7 条反例。\n *\n * 第 23 轮（2026-10-03）「亮度证据熄屏门」：用户报「亮度调到最低后看锁屏卡片，歌词\n * 不再滚动（8.3Hz 时钟被停）」。根因：UIScreen.brightness 的 0.0 就是「最低亮度」，\n * 用 brightness > 0 判「亮屏」→ 最低亮度被误判成熄屏；且最低亮度下亮/灭屏亮度恒为 0\n * （可能连亮度变化通知都不发），误判后无法自愈。修法：亮度证据 LXLastNonZeroBrightness\n * （只在读到非零亮度时更新）+ 阈值 LXScreenOffTrustBrightness = 0.3（不得低于 0.2）——\n * 亮度 0 时只有「刚才明显亮过」才认定熄屏，其余（最低亮度 / 暗环境自动亮度 / 渐暗到 0 /\n * 从未观测到非零亮度）一律按亮。证据挂两处：亮度变化通知（先记录再判定，顺序不能反——\n * 硬关屏那一次通知只有这一次机会拿到依据）+ 回前台；用调用点计数而非窗口正则，避免相邻\n * 观察者互相顶包。绑住：新增 1 组不变量（共 5 组）+ 3 条反例（共 25 条）。\n *\n * 第 33 轮第 1 条（2026-10-08）「发热严重，减少发热量，特别是减少后台运行占用，优化整体\n * 代码，去除冗余代码无用代码」：前几组治「音频常驻时后台跑一整夜的活」，这一组治**后台每\n * N 秒起床一次**的三处周期性 JS 工作（倒计时 UI tick / 首页横滑自愈心跳 / 网易登录 cookie\n * 轮询）——单次不重，但每次唤醒都把 CPU 从深度睡眠里拽起来。口径是**闸门 ≠ 停表**：定时器\n * 保留（普通 setInterval，后台被系统冻结）、body 早退、回前台自动恢复；倒计时到点的\n * BackgroundTimer 与回前台两处自愈兜底一个都不许删。另一半是冗余清理（52 个无引用文件已\n * 删）：按「路径必须不存在 + 正向对照 + 全量 import 解析扫描」三向钉住 —— 本机没有\n * tsc/eslint，删过头只有这道扫描拦得住。绑住：新增 2 组不变量（共 7 组）+ 9 条反例（共 35 条）。\n *\n * 第 61 轮第 3 条（2026-10-11）「当我右滑时，底部 tab 栏和迷你播放器栏透过的画面是由右\n * 向左滑入的，这个方向是反的，需要改」：玻璃转场语义**反转** —— 第 52~60 轮的「返回露出\n * 门」（revealWindow.ts / navRevealing / NAV_REVEAL_*）与原生自恢复通道整条删除，改成\n * 整段 push/pop 转场里玻璃**按住**，按住条件合进玻璃专用门：useGlassHomeCovered /\n * useGlassCovered = 账本门 ∨ useGlassNavHold，useGlassNavHold = useNavTransitioning ∧\n * !usePagerDragging（拖页手势会话一开始就退出按住、恢复实时采景；转场结束由原生\n * handleResumeFromPause 收口）。§[玻璃覆盖暂停链路] 的消费点口径随之收紧：paused 里\n * **不许再直接串 navTransitioning / navRevealing**（旧的「允许再或上转场窗口条件」是\n * 第 59/60 轮形态，已删除）—— 直接串会绕开 !dragging 让行口、也把窗口状态漏进每块玻璃\n * 的渲染门。窗口链路本体的完整验证已由 scripts/sim-glass-nav-hold.js 单点钉住，本脚本\n * 只钉消费点形态。绑住：§④ 新增负向断言 2 条 + 反例 P8/P9（反例总数 35 → 37）。\n */\n\nconst fs = require('fs')\nconst path = require('path')\n\nconst ROOT = path.join(__dirname, '..')\nconst read = (p) => fs.readFileSync(path.join(ROOT, p), 'utf8').replace(/\\r\\n/g, '\\n')\n\nconst APPDEL = 'ios/LxMusicMobile/AppDelegate.mm'\nconst PLAY_PROGRESS = 'src/core/init/player/playProgress.ts'\n\nconst REAL = {\n  appdel: read(APPDEL),\n  playProgress: read(PLAY_PROGRESS),\n}\n\nconst stripComments = (src) =>\n  src.replace(/\\/\\*[\\s\\S]*?\\*\\//g, '').replace(/\\/\\/[^\\n]*/g, '')\n\n// ---------------------------------------------------------------------------\n// 原生歌词时钟：必须「可停」，且热路径不得留 NSLog\n// ---------------------------------------------------------------------------\n\n/** 从源码抽出某个 C 函数【定义】体（按大括号配平）；跳过前置声明（`)` 后是 `;` 而非 `{`）。 */\nconst extractCFunction = (src, signature) => {\n  let searchFrom = 0\n  for (;;) {\n    const start = src.indexOf(signature, searchFrom)\n    if (start < 0) return null\n    const parenEnd = src.indexOf(')', start + signature.length - 1)\n    // signature 以 '(' 结尾时，parenEnd 是本函数的参数表右括号\n    if (parenEnd < 0) return null\n    let i = parenEnd + 1\n    while (i < src.length && /\\s/.test(src[i])) i++\n    if (src[i] === '{') {\n      // 命中定义：从 { 起配平\n      let depth = 0\n      for (let j = i; j < src.length; j++) {\n        const ch = src[j]\n        if (ch === '{') depth++\n        else if (ch === '}') {\n          depth--\n          if (depth === 0) return src.slice(start, j + 1)\n        }\n      }\n      return null\n    }\n    // 是声明（;）→ 继续往后找同名定义\n    searchFrom = start + signature.length\n  }\n}\n\nconst nativeInvariants = (src) => {\n  const raw = src\n  const code = stripComments(src)\n  const reasons = []\n\n  // 1) 必须有「停止歌词时钟」的实现：dispatch_source_cancel(timer) 且把静态变量置 nil\n  if (!/static\\s+void\\s+LXStopNowPlayingLyricTimer\\s*\\(\\s*void\\s*\\)/.test(code)) {\n    reasons.push('缺少 LXStopNowPlayingLyricTimer()：时钟一旦创建永不停止 = 后台 8.3Hz 永久唤醒')\n  } else {\n    const body = extractCFunction(code, 'static void LXStopNowPlayingLyricTimer(void)')\n    if (!body || !/dispatch_source_cancel\\s*\\(/.test(body)) {\n      reasons.push('LXStopNowPlayingLyricTimer 未 dispatch_source_cancel 时钟（仅置 nil 会泄漏 dispatch source）')\n    }\n    if (!/LXNowPlayingLyricTimer\\s*=\\s*nil/.test(body)) {\n      reasons.push('LXStopNowPlayingLyricTimer 未把 LXNowPlayingLyricTimer 置 nil（之后无法重启）')\n    }\n  }\n\n  // 2) 时钟生命周期必须有「按播放态同步」的统一守卫，且被关键路径调用：\n  //    - LXSyncNowPlayingLyricTimer 定义存在，且在非 Playing 时走停钟\n  //    - 播放态切换（LXSetNowPlayingPlaybackState）、元数据发布（LXSetNowPlayingInfo）、\n  //      清空会话（LXClearNowPlayingInfo）三处都必须调用它\n  if (!/static\\s+void\\s+LXSyncNowPlayingLyricTimer\\s*\\(\\s*void\\s*\\)/.test(code)) {\n    reasons.push('缺少 LXSyncNowPlayingLyricTimer()：无法按播放态停/启 8.3Hz 时钟')\n  } else {\n    const syncBody = extractCFunction(code, 'static void LXSyncNowPlayingLyricTimer(void)')\n    if (!syncBody || !/LXStopNowPlayingLyricTimer\\s*\\(\\s*\\)/.test(syncBody)) {\n      reasons.push('LXSyncNowPlayingLyricTimer 未在非 Playing 时停钟')\n    }\n    if (!syncBody || !/LXStartNowPlayingLyricTimer\\s*\\(\\s*\\)/.test(syncBody)) {\n      reasons.push('LXSyncNowPlayingLyricTimer 未在 Playing 时启钟')\n    }\n    // 三处关键路径调用点\n    for (const [sig, label] of [\n      ['static void LXSetNowPlayingPlaybackState(', '播放态切换'],\n      ['static void LXSetNowPlayingInfo(', '元数据发布'],\n      ['static void LXClearNowPlayingInfo(void)', '清空会话'],\n    ]) {\n      const body = extractCFunction(code, sig)\n      if (!body) { reasons.push(`未找到 ${sig}`); continue }\n      if (!/LXSyncNowPlayingLyricTimer\\s*\\(\\s*\\)/.test(body)) {\n        reasons.push(`${label}（${sig}）未调用 LXSyncNowPlayingLyricTimer（该路径会漏掉停/启钟）`)\n      }\n    }\n    // 歌词时间轴注入也必须走统一守卫（而非自行无条件启钟）\n    const setLines = extractCFunction(code, 'static void LXSetNowPlayingLyricLines(')\n    if (setLines && !/LXSyncNowPlayingLyricTimer\\s*\\(\\s*\\)/.test(setLines)) {\n      reasons.push('LXSetNowPlayingLyricLines 未走统一守卫（自行启钟会在暂停态误开 8.3Hz）')\n    }\n  }\n\n  // 3) 热路径不得留 NSLog：tick（每次换行）+ setNowPlayingLyrics（每次设行）\n  const step = extractCFunction(code, 'static void LXNowPlayingLyricStep(void)')\n  if (step && /NSLog\\s*\\(/.test(step)) {\n    reasons.push('LXNowPlayingLyricStep 内含 NSLog（每次换行同步写系统日志，锁屏期唤醒 I/O）')\n  }\n  const setLinesN = extractCFunction(code, 'static void LXSetNowPlayingLyricLines(')\n  if (setLinesN && /NSLog\\s*\\(/.test(setLinesN)) {\n    reasons.push('LXSetNowPlayingLyricLines 内含 NSLog（每次设行同步写系统日志）')\n  }\n\n  // 4) 时钟周期契约值 0.05s【第 47 轮】：用户原话「歌词显示需要更加迅速和提高加载帧率」，\n  //    周期从 0.12s（8.3Hz）上调到 0.05s（20Hz），把最坏换行延迟从 120ms 压到 50ms。\n  //    仍然钉死确切值：这一拍是「换行延迟」与「唤醒频率」的取舍点，任何改动（改大＝歌词\n  //    变慢、改小＝唤醒变密）都必须显式过一遍本断言，不许顺手漂移。\n  //    必须钉在**时钟那一行**的实参上：光测「全文件存在 0.05」会被封面重发路径里同值的\n  //    0.05s dispatch_after 蒙混过关（锚点漂移而断言照样绿）。两个实参都抓：start 只决定\n  //    第一拍，interval 才是重复频率。\n  //    省电口径不受影响：时钟只在「播放中且屏幕可信为亮」时存在，暂停/熄屏/清空歌词一律停钟。\n  const timerPeriod = /dispatch_source_set_timer\\(timer,\\s*\\n\\s*dispatch_time\\(DISPATCH_TIME_NOW, \\(int64_t\\)\\(([0-9.]+) \\* NSEC_PER_SEC\\)\\),\\s*\\n\\s*\\(uint64_t\\)\\(([0-9.]+) \\* NSEC_PER_SEC\\),/.exec(code)\n  if (timerPeriod == null) {\n    reasons.push('找不到歌词时钟的周期（锚点漂移：dispatch_source_set_timer 的 dispatch_time / 间隔行）')\n  } else if (Number(timerPeriod[1]) !== 0.05 || Number(timerPeriod[2]) !== 0.05) {\n    reasons.push(`歌词时钟周期不再是 0.05s（第 47 轮契约值：用户要求歌词更迅速、帧率更高，定为 20Hz；当前 start=${timerPeriod[1]}s interval=${timerPeriod[2]}s）`)\n  }\n\n  return { ok: reasons.length === 0, reasons }\n}\n\n// ---------------------------------------------------------------------------\n// JS 侧：后台不得让背景定时器空转申请后台任务断言\n// ---------------------------------------------------------------------------\n\n/** 从源码抽出一个「const/let/var name = ...」声明体（按大括号配平），供 arrow function 用。 */\nconst extractAssignment = (src, decl) => {\n  const start = src.indexOf(decl)\n  if (start < 0) return null\n  const braceStart = src.indexOf('{', start)\n  if (braceStart < 0) return null\n  // 反向确认 `{` 之前没有 `;`（否则说明这个声明体不含块，是表达式）\n  const head = src.slice(start, braceStart)\n  if (head.includes(';')) return null\n  let depth = 0\n  for (let i = braceStart; i < src.length; i++) {\n    const ch = src[i]\n    if (ch === '{') depth++\n    else if (ch === '}') {\n      depth--\n      if (depth === 0) return src.slice(start, i + 1)\n    }\n  }\n  return null\n}\n\nconst jsInvariants = (src) => {\n  const code = stripComments(src)\n  const reasons = []\n\n  // 1) 慢校准 1s tick 的 body 必须有 AppState 前台守卫（后台直接 return，\n  //    不做桥往返 / React 发布；定时器本身每秒申请断言的成本靠原生侧停钟与\n  //    守卫共同压制，这里先保证「后台不做重活」）\n  const getCurrentTime = extractAssignment(code, 'const getCurrentTime =')\n  if (!getCurrentTime) {\n    reasons.push('未找到 getCurrentTime（慢校准 tick body）')\n  } else if (!/AppState\\.currentState\\s*!==\\s*'active'/.test(getCurrentTime)) {\n    reasons.push('getCurrentTime 无 AppState 前台守卫（后台会做桥往返 + React 发布）')\n  }\n\n  // 2) 原生 4Hz 位置事件回调同样必须有前台守卫\n  const onPos = code.indexOf('onPlayerPosition(')\n  if (onPos < 0) {\n    reasons.push('未找到 onPlayerPosition 订阅')\n  } else if (!/AppState\\.currentState\\s*!==\\s*'active'/.test(code.slice(onPos, onPos + 400))) {\n    reasons.push('onPlayerPosition 回调无 AppState 前台守卫（后台仍会被 4Hz 事件唤醒做 React 发布）')\n  }\n\n  // 3) 1s 慢校准 tick 不得用 BackgroundTimer.setInterval：\n  //    react-native-background-timer 原生每拍都 beginBackgroundTaskWithName:\n  //    （申请后台任务断言 + 阻止挂起），而本 tick 后台被守卫早退、毫无意义 →\n  //    纯属每秒一次的净耗电。必须用普通 setInterval（后台冻结，无断言）。\n  const startUpdate = extractAssignment(code, 'const startUpdateTimeout =')\n  if (!startUpdate) {\n    reasons.push('未找到 startUpdateTimeout（慢校准 tick 启动点）')\n  } else {\n    if (/BackgroundTimer\\.setInterval/.test(startUpdate)) {\n      reasons.push('慢校准 tick 用了 BackgroundTimer.setInterval（每秒申请后台任务断言，后台净耗电）')\n    }\n    if (!/\\bsetInterval\\s*\\(/.test(startUpdate)) {\n      reasons.push('慢校准 tick 未使用普通 setInterval（后台需要它被系统冻结、零断言）')\n    }\n  }\n\n  return { ok: reasons.length === 0, reasons }\n}\n\n// ---------------------------------------------------------------------------\n// 反例（对篡改后的源码跑同一套判断，必须被拦下）\n// ---------------------------------------------------------------------------\n\nconst tamper = (src, find, replace) => {\n  if (!src.includes(find)) throw new Error(`tamper 锚点未命中: ${find}`)\n  return src.replace(find, replace)\n}\n\nconst runCounterExamples = () => {\n  const results = []\n\n  const check = (name, fn, expectReasonSubstr) => {\n    let reasons = []\n    try {\n      reasons = fn()\n    } catch (e) {\n      results.push({ name, ok: false, detail: `抛异常: ${e.message}` })\n      return\n    }\n    const hit = reasons.some(r => r.includes(expectReasonSubstr))\n    results.push({ name, ok: hit, detail: hit ? '已拦下' : `未拦下（reasons=${JSON.stringify(reasons)}）` })\n  }\n\n  // — 原生反例 —\n  // ① 删掉停钟函数 → 应报「缺少 LXStopNowPlayingLyricTimer」\n  check('原生① 无停钟函数', () => {\n    const s = REAL.appdel.replace(/static\\s+void\\s+LXStopNowPlayingLyricTimer\\s*\\(\\s*void\\s*\\)[^}]*\\{[\\s\\S]*?\\n\\}/, '')\n    return nativeInvariants(s).reasons\n  }, '缺少 LXStopNowPlayingLyricTimer')\n\n  // ② 停钟函数里不 cancel → 报「未 dispatch_source_cancel」\n  check('原生② 停钟不 cancel', () => {\n    const s = tamper(REAL.appdel, 'dispatch_source_cancel(LXNowPlayingLyricTimer);', '/*removed*/;')\n    return nativeInvariants(s).reasons\n  }, '未 dispatch_source_cancel')\n\n  // ③ 停钟不再被统一守卫调用（守卫删掉停钟分支）→ 报「未在非 Playing 时停钟」\n  check('原生③ 守卫不停钟', () => {\n    const s = tamper(REAL.appdel,\n      'if (LXNowPlayingState == MPNowPlayingPlaybackStatePlaying && !LXIsScreenTrustedOff()) {\\n    LXStartNowPlayingLyricTimer();\\n  } else {\\n    LXStopNowPlayingLyricTimer();\\n  }',\n      'LXStartNowPlayingLyricTimer();')\n    return nativeInvariants(s).reasons\n  }, '未在非 Playing 时停钟')\n\n  // ③b 播放态切换处漏掉统一守卫 → 报「播放态切换…未调用」\n  check('原生③b 播放态切换漏调守卫', () => {\n    const s = tamper(REAL.appdel,\n      '  // 播放/暂停/停止切换时同步时钟生命周期：暂停/停止即停钟（20Hz 在非播放态是\\n  // 净唤醒，锁屏后台耗电），恢复播放时重建。放在早退（无标题）之前——即使元数据\\n  // 尚未到达，暂停已成立，时钟就不该继续跑。\\n  LXSyncNowPlayingLyricTimer();\\n',\n      '')\n    return nativeInvariants(s).reasons\n  }, '播放态切换')\n\n  // ④ tick 里加回 NSLog → 报「LXNowPlayingLyricStep 内含 NSLog」\n  check('原生④ tick 恢复 NSLog', () => {\n    const s = tamper(REAL.appdel, 'LXNowPlayingLyricIndex = found;',\n      'LXNowPlayingLyricIndex = found;\\n    NSLog(@\"[LXLyric] %@\", text);')\n    return nativeInvariants(s).reasons\n  }, 'LXNowPlayingLyricStep 内含 NSLog')\n\n  // ⑤ 时钟周期改成 1s → 报「周期不再是 0.05s」\n  check('原生⑤ 周期漂移', () => {\n    const s2 = REAL.appdel.replace(/0\\.05 \\* NSEC_PER_SEC/g, '1.0 * NSEC_PER_SEC')\n    return nativeInvariants(s2).reasons\n  }, '周期不再是 0.05s')\n\n  // — JS 反例 —\n  // ⑥ 删掉 getCurrentTime 的 AppState 守卫 → 报「无 AppState 前台守卫」\n  check('JS⑥ 慢校准无前台守卫', () => {\n    const s = tamper(REAL.playProgress,\n      \"if (AppState.currentState !== 'active') return\\n    let id = playerState.musicInfo.id\",\n      'let id = playerState.musicInfo.id')\n    return jsInvariants(s).reasons\n  }, 'getCurrentTime 无 AppState 前台守卫')\n\n  // ⑦ 删掉 4Hz 回调的守卫 → 报「onPlayerPosition 回调无 AppState 前台守卫」\n  check('JS⑦ 位置事件无前台守卫', () => {\n    const s = tamper(REAL.playProgress,\n      \"onPlayerPosition((position, rate) => {\\n    if (AppState.currentState !== 'active') return\\n\",\n      'onPlayerPosition((position, rate) => {\\n')\n    return jsInvariants(s).reasons\n  }, 'onPlayerPosition 回调无 AppState 前台守卫')\n\n  // ⑧ 慢校准 tick 改回 BackgroundTimer.setInterval → 报「每秒申请后台任务断言」\n  check('JS⑧ 慢校准回退 BackgroundTimer', () => {\n    const s = tamper(REAL.playProgress,\n      'updateTimeout = setInterval(() => {',\n      'updateTimeout = BackgroundTimer.setInterval(() => {')\n    return jsInvariants(s).reasons\n  }, '每秒申请后台任务断言')\n\n  return results\n}\n\n// ---------------------------------------------------------------------------\n// 玻璃「覆盖暂停」链路（2026-09-30 新增）：不可见的 MTKView 不得逐帧渲染\n// ---------------------------------------------------------------------------\n\nconst GLASS_FILES = {\n  effectView: 'ios/Vendor/LiquidGlassKit/Sources/LiquidGlassEffectView.swift',\n  manager: 'ios/Vendor/LiquidGlassKit/Sources/LiquidGlassViewManager.mm',\n  comp: 'src/components/common/LiquidGlass.tsx',\n  tabbar: 'src/components/layout/ModernTabBar.tsx',\n  playerbar: 'src/components/player/PlayerBar/index.tsx',\n  hookCommon: 'src/store/common/hook.ts',\n  playingIcon: 'src/components/common/PlayingIcon.tsx',\n}\n\nconst readGlass = (over = {}) => {\n  const files = {}\n  for (const [k, p] of Object.entries(GLASS_FILES)) {\n    files[k] = over[k] ?? read(p)\n  }\n  return files\n}\n\nconst pausedInvariants = (files) => {\n  const reasons = []\n  // ① 原生入口：EffectView.setPaused 转发 MTKView.isPaused\n  if (!/@objc\\s+public\\s+func\\s+setPaused\\(_\\s+paused:\\s*Bool\\)/.test(files.effectView)) {\n    reasons.push('LiquidGlassEffectView 缺 setPaused:（省电门无原生入口）')\n  }\n  if (!/liquidGlassView\\?\\.isPaused\\s*=\\s*paused/.test(files.effectView)) {\n    reasons.push('setPaused: 未落到 MTKView.isPaused（暂停不生效）')\n  }\n  // ② manager：protocol 声明 + host applyPaused:（respondsToSelector 分流）+ 缓存重放 + prop\n  if (!/- \\(void\\)setPaused:\\(BOOL\\)paused;/.test(files.manager)) {\n    reasons.push('LGGlassBackingCustomizations 缺 setPaused: 声明（磨砂档无分流依据）')\n  }\n  if (!/- \\(void\\)applyPaused:\\(BOOL\\)paused/.test(files.manager)) {\n    reasons.push('宿主缺 applyPaused:（缓存 + respondsToSelector 分流）')\n  }\n  // 定位 reapply 函数【定义体】（不能 indexOf 首次出现——installGlassBacking 里\n  // 的调用处在定义之前，从那里 +400 字符看不到 applyPaused）\n  const reapplyAt = files.manager.indexOf('- (void)reapplyCachedPropsToBacking')\n  if (reapplyAt < 0 || !/applyPaused:_paused/.test(files.manager.slice(reapplyAt, reapplyAt + 400))) {\n    reasons.push('reapplyCachedPropsToBacking 未重放 paused（覆盖下切液态开关会丢暂停态、恢复渲染）')\n  }\n  if (!/RCT_CUSTOM_VIEW_PROPERTY\\(paused,\\s*NSNumber,\\s*LGLiquidGlassHostView\\)/.test(files.manager)) {\n    reasons.push('manager 缺 paused prop（JS 门控传不到原生）')\n  }\n  // ③ JS 组件：paused 声明 + 透传\n  if (!/paused\\?\\s*:\\s*boolean/.test(files.comp)) {\n    reasons.push('LiquidGlass.tsx 缺 paused prop 声明')\n  }\n  if (!/paused=\\{paused\\}/.test(files.comp)) {\n    reasons.push('LiquidGlass.tsx 未透传 paused（声明了但没接）')\n  }\n  // ④ 消费点：TabBar 按全局 Home 判定；PlayerBar 按所属屏幕 componentId 判定。\n  // 【第 52 轮第 2 条（2026-10-11）→ 第 61 轮第 3 条】门是**玻璃专用**门：\n  //   glassHomeCovered = useGlassHomeCovered()（= useHomeCovered() ∨ useGlassNavHold()）\n  //   glassCovered     = useGlassCovered(componentId)（= useScreenCovered(componentId) ∨ useGlassNavHold()）\n  //   useGlassNavHold  = useNavTransitioning() ∧ !usePagerDragging()\n  // 第 61 轮把转场语义**反转**：整段 push/pop 转场里玻璃要**按住**（用户原话「当我右滑\n  // 时，底部 tab 栏和迷你播放器栏透过的画面是由右向左滑入的，这个方向是反的，需要改」\n  // —— 返回转场里玻璃背后是正在滑走的那一页，实时重采就是把它采进胶囊）。转场结束由\n  // 原生 handleResumeFromPause 收口；!dragging 是让行口：拖 Home Pager 手势会话一开始\n  // 就退出按住、恢复实时采景。第 52~60 轮的「返回露出门」（revealWindow.ts /\n  // navRevealing / NAV_REVEAL_*）与原生自恢复通道已整条删除，别改回去。\n  // 为什么必须有玻璃门：账本（componentIds）要等 RNN screenPopped 才翻，晚于用户按下\n  // 返回；玻璃门在**派发 pop 之前**就把「被覆盖 / 转场中」并入。账本门本体与它的非玻璃\n  // 消费点一个字不动（见 ⑤；窗口链路与消费点的完整验证由 scripts/sim-glass-nav-hold.js\n  // 单点钉住，本脚本不重复钉那一段）。\n  // 匹配口径（2026-10-01 C-9 补充，沿用并收紧）：玻璃门允许再或上「本块玻璃当前不可见」\n  // 的条件（收起态圆钮玻璃在展开态不可见、展开态胶囊玻璃在收起态不可见，两边都该停帧），\n  // 故写成 paused={glassHomeCovered} 或 paused={glassHomeCovered || <不可见条件>} 都算达标；\n  // 但玻璃门**必须是第一个析取项** —— 少了它才是真缺陷（被压栈页覆盖仍逐帧渲染白烧）。\n  // 【第 61 轮第 3 条收紧】paused 里**不许再直接串 navTransitioning / navRevealing**：\n  // 按住已合进 useGlassNavHold 门内，直接串会绕开它的 !dragging 让行口，也把窗口状态\n  // 漏进每一块玻璃的渲染门。下面对两条栏各配一条反例（P8 / P9）。\n  if (!/useGlassHomeCovered\\(\\)/.test(files.tabbar) || !/paused=\\{glassHomeCovered\\s*(\\|\\|[^}]*)?\\}/.test(files.tabbar)) {\n    reasons.push('ModernTabBar 未接 paused={glassHomeCovered}(||…)（Tab 栏玻璃被覆盖/转场中仍逐帧渲染：白烧 + 返回转场里会采到正在滑走的那一页）')\n  }\n  {\n    const bindings = files.tabbar.match(/paused=\\{[^}]*\\}/g) ?? []\n    if (bindings.some((s) => /navTransitioning|navRevealing/.test(s))) {\n      reasons.push('ModernTabBar 的 paused 又把 navTransitioning / navRevealing 直接串回玻璃门（第 61 轮第 3 条：按住已合进 useGlassNavHold，直接串会绕开 !dragging 让行口）')\n    }\n  }\n  // 同一口径：PlayerBar 也允许再或上「本块玻璃此刻不该渲染」的条件（收起/展开态、\n  // !appActive 前台门），但玻璃门必须是**第一个析取项**，且同样不许直接串转场状态\n  // —— 少了玻璃门才是真缺陷（被压栈页覆盖仍逐帧渲染白烧）。\n  if (!/useGlassCovered\\(componentId\\)/.test(files.playerbar) || !/paused=\\{glassCovered\\s*(\\|\\|[^}]*)?\\}/.test(files.playerbar)) {\n    reasons.push('PlayerBar 未接 paused={glassCovered}(||…)（迷你条玻璃被覆盖/转场中仍逐帧渲染：白烧 + 返回转场里会采到正在滑走的那一页）')\n  }\n  {\n    const bindings = files.playerbar.match(/paused=\\{[^}]*\\}/g) ?? []\n    if (bindings.some((s) => /navTransitioning|navRevealing/.test(s))) {\n      reasons.push('PlayerBar 的 paused 又把 navTransitioning / navRevealing 直接串回玻璃门（第 61 轮第 3 条：按住已合进 useGlassNavHold，直接串会绕开 !dragging 让行口）')\n    }\n  }\n  // ⑤ 覆盖判定 hook 本体\n  if (!/export const useHomeCovered/.test(files.hookCommon) || !/export const useScreenCovered/.test(files.hookCommon)) {\n    reasons.push('store/common/hook 缺 useHomeCovered / useScreenCovered（覆盖判定无从派生）')\n  }\n  // ⑥ PlayingIcon（列表「正在播放」循环动画）必须有覆盖门控\n  if (!/isPlay\\s*&&\\s*!homeCovered/.test(files.playingIcon)) {\n    reasons.push('PlayingIcon 缺覆盖门控（Home 被覆盖时循环动画仍每帧驱动）')\n  }\n  return reasons\n}\n\nconst runPausedCounterExamples = () => {\n  const results = []\n  const check = (name, files, expectSubstr) => {\n    const hits = pausedInvariants(files)\n    results.push({ name, ok: hits.some(r => r.includes(expectSubstr)), detail: hits })\n  }\n  // P1 抹掉原生入口\n  check('P1 EffectView 抹掉 setPaused', readGlass({\n    effectView: read(GLASS_FILES.effectView).replace(/@objc public func setPaused\\(_ paused: Bool\\) \\{[\\s\\S]*?\\n    \\}/, ''),\n  }), '缺 setPaused:')\n  // P2 抹掉 paused prop\n  check('P2 manager 抹掉 paused prop', readGlass({\n    manager: read(GLASS_FILES.manager).replace('RCT_CUSTOM_VIEW_PROPERTY(paused, NSNumber, LGLiquidGlassHostView) {', 'REMOVED(paused, NSNumber, LGLiquidGlassHostView) {'),\n  }), '缺 paused prop')\n  // P3 抹掉重放（覆盖下切开关丢暂停态）\n  check('P3 manager 抹掉 paused 重放', readGlass({\n    manager: read(GLASS_FILES.manager).replace('[self applyPaused:_paused];', ''),\n  }), '未重放 paused')\n  // P4 JS 未透传\n  check('P4 LiquidGlass 抹掉透传', readGlass({\n    comp: read(GLASS_FILES.comp).replace('paused={paused}', 'removedX={paused}'),\n  }), '未透传 paused')\n  // P5 消费点脱钩（第 52 轮：门名换成玻璃专用门）\n  check('P5 TabBar 抹掉 paused', readGlass({\n    tabbar: read(GLASS_FILES.tabbar).replace(/paused=\\{glassHomeCovered\\s*(\\|\\|[^}]*)?\\}/g, 'removedX={glassHomeCovered}'),\n  }), 'ModernTabBar 未接')\n  check('P6 PlayingIcon 恢复无条件动画', readGlass({\n    playingIcon: read(GLASS_FILES.playingIcon).replace('const active = isPlay && !homeCovered', 'const active = isPlay'),\n  }), 'PlayingIcon 缺覆盖门控')\n  // P7：PlayerBar 消费点脱钩（与 P5 同款反例，覆盖 2026-10-01 新加的 ||… 分支）\n  check('P7 PlayerBar 抹掉 paused', readGlass({\n    playerbar: read(GLASS_FILES.playerbar).replace(/paused=\\{glassCovered\\s*(\\|\\|[^}]*)?\\}/g, 'removedX={glassCovered}'),\n  }), 'PlayerBar 未接')\n  // P8/P9（第 61 轮第 3 条新增）：paused 里又直接串转场状态 —— 绕开 useGlassNavHold 的\n  // !dragging 让行口（拖页手势会话里玻璃被误按停），必须判红。锚点为两条栏各自那个\n  // 「|| 不可见条件」绑定，全文件唯一（TabBar 另一处是 !collapsed 变体，不会命中）。\n  check('P8 TabBar paused 又串 navTransitioning', readGlass({\n    tabbar: read(GLASS_FILES.tabbar).replace('paused={glassHomeCovered || collapsed || !appActive}', 'paused={glassHomeCovered || navTransitioning || collapsed || !appActive}'),\n  }), '直接串回玻璃门')\n  check('P9 PlayerBar paused 又串 navTransitioning', readGlass({\n    playerbar: read(GLASS_FILES.playerbar).replace('paused={glassCovered || !appActive}', 'paused={glassCovered || navTransitioning || !appActive}'),\n  }), '直接串回玻璃门')\n  return results\n}\n\n// ---------------------------------------------------------------------------\n// 「后台不可见即停」链路（2026-10-02 新增，用户第 8 条）：\n// 音频后台常驻时，只有前台才需要的工作必须随 App 退到后台而停，否则跑一整夜\n// ---------------------------------------------------------------------------\n\nconst BG_FILES = {\n  tabbar: 'src/components/layout/ModernTabBar.tsx',\n  playerbar: 'src/components/player/PlayerBar/index.tsx',\n  hookCommon: 'src/store/common/hook.ts',\n  playerHook: 'src/plugins/player/hook.ts',\n  fsIos: 'src/utils/fs.ios.ts',\n}\n\nconst readBg = (over = {}) => {\n  const files = {}\n  for (const [k, p] of Object.entries(BG_FILES)) {\n    files[k] = over[k] ?? read(p)\n  }\n  return files\n}\n\nconst bgInvariants = (files) => {\n  const reasons = []\n  // ① 前台判定 hook 本体（响应式；不能只有 utils/tools 里那个非响应式的 isActive）\n  if (!/export const useAppActive/.test(files.hookCommon)) {\n    reasons.push('store/common/hook 缺 useAppActive（前台门无从派生）')\n  }\n  // ② Tab 栏两块玻璃（展开态衬底带 + 收起态圆钮）都必须接前台门\n  if (!/const appActive = useAppActive\\(\\)/.test(files.tabbar)) {\n    reasons.push('ModernTabBar 缺 useAppActive（Tab 栏玻璃前台门缺失）')\n  }\n  const tabPaused = files.tabbar.match(/paused=\\{[^}]*\\}/g) ?? []\n  const tabGated = tabPaused.filter(s => /!\\s*appActive\\b/.test(s)).length\n  if (tabGated < 2) {\n    reasons.push(`ModernTabBar 前台门未覆盖两块玻璃（paused 含 !appActive 的只有 ${tabGated} 处，应为 2）`)\n  }\n  // ③ 迷你播放器玻璃 + useMemo 依赖（漏依赖 = 前后台变化不重建节点，门形同虚设）\n  if (!/const appActive = useAppActive\\(\\)/.test(files.playerbar)) {\n    reasons.push('PlayerBar 缺 useAppActive（迷你条玻璃前台门缺失）')\n  }\n  const pbPaused = files.playerbar.match(/paused=\\{[^}]*\\}/g) ?? []\n  if (!pbPaused.some(s => /!\\s*appActive\\b/.test(s))) {\n    reasons.push('PlayerBar 前台门未接（paused 不含 !appActive）')\n  }\n  const deps = files.playerbar.match(/\\n\\s*\\[glassOpacity,[^\\]\\n]*\\]/)\n  if (!deps || !/\\bappActive\\b/.test(deps[0])) {\n    reasons.push('PlayerBar useMemo 依赖未含 appActive（前台门变化不会重建节点）')\n  }\n  // ④ 缓冲进度轮询：起表点收敛到一处 + 前台门 + 前后台订阅\n  const itvCount = (files.playerHook.match(/setInterval\\(updateBuffer/g) ?? []).length\n  if (itvCount !== 1) {\n    reasons.push(`useBufferProgress 起表点未收敛（setInterval(updateBuffer 出现 ${itvCount} 次，应为 1 次、只在 syncItv 内）`)\n  }\n  if (!/if\\s*\\(!wantPolling\\s*\\|\\|\\s*!isActive\\(\\)\\)\\s*return/.test(files.playerHook)) {\n    reasons.push('缓冲轮询缺前台门（syncItv 里 !wantPolling || !isActive() 守卫缺失）')\n  }\n  if (!/AppState\\.addEventListener\\('change'/.test(files.playerHook) ||\n      !/appStateSubscription\\.remove\\(\\)/.test(files.playerHook)) {\n    reasons.push('缓冲轮询缺前后台订阅（退后台不停表 / 回前台不补测）')\n  }\n  // ⑤ 下载进度限流（RNFS 默认 progressInterval=0 即逐块回调）\n  if (!/const DOWNLOAD_PROGRESS_INTERVAL = 250/.test(files.fsIos) ||\n      !/progressInterval:\\s*DOWNLOAD_PROGRESS_INTERVAL/.test(files.fsIos)) {\n    reasons.push('downloadFile 未统一限流 progressInterval: 250（逐块回调照旧高频唤醒 JS）')\n  }\n  return reasons\n}\n\nconst runBgCounterExamples = () => {\n  const results = []\n  const check = (name, files, expectSubstr) => {\n    const hits = bgInvariants(files)\n    results.push({ name, ok: hits.some(r => r.includes(expectSubstr)), detail: hits })\n  }\n  // B1 Tab 栏两块玻璃一起脱钩\n  check('B1 TabBar 抹掉前台门', readBg({\n    tabbar: read(BG_FILES.tabbar).replace(/paused=\\{[^}]*!\\s*appActive[^}]*\\}/g, 'paused={homeCovered}'),\n  }), 'ModernTabBar 前台门未覆盖两块玻璃')\n  // B2 Tab 栏不订阅前台状态\n  check('B2 TabBar 抹掉 useAppActive', readBg({\n    tabbar: read(BG_FILES.tabbar).replace('const appActive = useAppActive()', 'const appActive = true'),\n  }), 'ModernTabBar 缺 useAppActive')\n  // B3 迷你条玻璃脱钩\n  check('B3 PlayerBar 抹掉前台门', readBg({\n    playerbar: read(BG_FILES.playerbar).replace(/paused=\\{[^}]*!\\s*appActive[^}]*\\}/, 'paused={screenCovered}'),\n  }), 'PlayerBar 前台门未接')\n  // B4 迷你条漏依赖（门在、节点不重建）\n  check('B4 PlayerBar 依赖数组漏 appActive', readBg({\n    playerbar: read(BG_FILES.playerbar).replace(', appActive,', ', '),\n  }), 'PlayerBar useMemo 依赖未含 appActive')\n  // B5 缓冲轮询把前台门去掉（回到「只要该轮询就起表」）\n  check('B5 缓冲轮询去掉前台门', readBg({\n    playerHook: read(BG_FILES.playerHook).replace('if (!wantPolling || !isActive()) return', 'if (!wantPolling) return'),\n  }), '缓冲轮询缺前台门')\n  // B6 缓冲轮询不订阅前后台变化（退后台不停表）\n  check('B6 缓冲轮询抹掉 AppState 订阅', readBg({\n    playerHook: read(BG_FILES.playerHook).replace(\"AppState.addEventListener('change'\", \"NoopState.addEventListener('change'\"),\n  }), '缓冲轮询缺前后台订阅')\n  // B7 下载进度回到逐块回调\n  check('B7 downloadFile 抹掉限流', readBg({\n    fsIos: read(BG_FILES.fsIos).replace('progressInterval: DOWNLOAD_PROGRESS_INTERVAL,', ''),\n  }), 'downloadFile 未统一限流')\n  return results\n}\n\n// ---------------------------------------------------------------------------\n// 「亮度证据」熄屏门（第 23 轮）：亮度 0 = 最低亮度 or 熄屏，判定必须带证据\n// ---------------------------------------------------------------------------\n\nconst SCREEN_GATE_THRESHOLD_MIN = 0.2\n\nconst screenGateInvariants = (src) => {\n  const reasons = []\n  const code = stripComments(src)\n\n  // ① 证据变量 + 阈值（不得低于 0.2：阈值收紧到 0 等于退回「亮度 0 即熄屏」的老错）\n  if (!/static\\s+double\\s+LXLastNonZeroBrightness\\s*=\\s*0;/.test(code)) {\n    reasons.push('缺少亮度证据 LXLastNonZeroBrightness（亮度 0 时无从判断「刚才明显亮过」）')\n  }\n  const thr = /static\\s+const\\s+double\\s+LXScreenOffTrustBrightness\\s*=\\s*([0-9.]+);/.exec(code)\n  if (!thr) {\n    reasons.push('缺少阈值 LXScreenOffTrustBrightness')\n  } else if (Number(thr[1]) < SCREEN_GATE_THRESHOLD_MIN) {\n    reasons.push(`熄屏阈值 ${thr[1]} 低于 ${SCREEN_GATE_THRESHOLD_MIN}（越收越紧 = 回到「亮度 0 即熄屏」的老错）`)\n  }\n\n  // ② 判定体：亮度非零 → 按亮；亮度 0 → 必须用「最近非零亮度」证据 + 阈值比较\n  const judge = extractCFunction(code, 'static BOOL LXIsScreenTrustedOff(void)')\n  if (!judge) {\n    reasons.push('缺少 LXIsScreenTrustedOff()（熄屏判定）')\n  } else {\n    if (!/UIScreen\\.mainScreen\\.brightness > 0/.test(judge)) {\n      reasons.push('熄屏判定缺「亮度非零即按亮」兜底')\n    }\n    if (!/LXLastNonZeroBrightness\\s*>=\\s*LXScreenOffTrustBrightness/.test(judge)) {\n      reasons.push('熄屏判定未用「最近非零亮度」证据（亮度 0 被直接当成熄屏 = 用户报的最低亮度冻歌词）')\n    }\n  }\n\n  // ③ 记录函数：0 不覆盖证据（0 就是被怀疑的那一侧，不能当证据）\n  const remember = extractCFunction(code, 'static void LXRememberScreenBrightness(void)')\n  if (!remember) {\n    reasons.push('缺少 LXRememberScreenBrightness()（亮度证据收集）')\n  } else {\n    if (!/if\\s*\\(brightness > 0\\)/.test(remember)) {\n      reasons.push('记录函数未把 0 挡在证据之外（0 会覆盖「最近非零亮度」→ 最低亮度被误判熄屏）')\n    }\n    if (!/LXLastNonZeroBrightness\\s*=\\s*brightness;/.test(remember)) {\n      reasons.push('记录函数未把亮度写进证据变量')\n    }\n  }\n\n  // ④ 证据必须挂在两处（用调用点计数，避免相邻观察者窗口正则互相顶包）：\n  //    亮度变化通知（先记录、后判定——顺序不能反）+ 回前台兜底\n  const recordCount = (code.match(/LXRememberScreenBrightness\\(\\)/g) ?? []).length\n  if (recordCount !== 2) {\n    reasons.push(`亮度证据的调用点是 ${recordCount} 处（应恰好 2：亮度变化通知 + 回前台兜底）`)\n  }\n  const brightnessAt = code.indexOf('UIScreenBrightnessDidChangeNotification')\n  if (brightnessAt < 0) {\n    reasons.push('未监听 UIScreenBrightnessDidChangeNotification（屏幕亮/灭无从取证）')\n  } else {\n    const block = code.slice(brightnessAt, code.indexOf('}];', brightnessAt))\n    const recordAt = block.indexOf('LXRememberScreenBrightness();')\n    const syncAt = block.indexOf('LXSyncNowPlayingLyricTimer();')\n    if (recordAt < 0) {\n      reasons.push('亮度变化通知里未记录证据（从亮屏硬关屏那一次通知是拿到依据的唯一机会）')\n    } else if (syncAt >= 0 && syncAt < recordAt) {\n      reasons.push('亮度通知里「先判定后记录」顺序反了（首次通知时证据还是旧值——必须先记录再判定）')\n    }\n  }\n  const activeAt = code.indexOf('UIApplicationDidBecomeActiveNotification')\n  if (activeAt < 0 || !code.slice(activeAt, code.indexOf('}];', activeAt)).includes('LXRememberScreenBrightness();')) {\n    reasons.push('回前台未记录亮度证据（最低亮度下亮/灭可能不发亮度通知，兜底取证点缺失）')\n  }\n\n  // ⑤ 门必须被统一守卫消费（否则证据齐备也只是摆设）\n  const syncBody = extractCFunction(code, 'static void LXSyncNowPlayingLyricTimer(void)')\n  if (!syncBody || !/LXIsScreenTrustedOff\\s*\\(\\s*\\)/.test(syncBody)) {\n    reasons.push('LXSyncNowPlayingLyricTimer 未消费熄屏判定（亮度门形同虚设，8.3Hz 照跑）')\n  }\n\n  return reasons\n}\n\nconst runScreenGateCounterExamples = () => {\n  const results = []\n  const check = (name, fn, expectSubstr) => {\n    let reasons = []\n    try {\n      reasons = fn()\n    } catch (e) {\n      results.push({ name, ok: false, detail: `抛异常: ${e.message}` })\n      return\n    }\n    const hit = reasons.some(r => r.includes(expectSubstr))\n    results.push({ name, ok: hit, detail: hit ? '已拦下' : `未拦下（reasons=${JSON.stringify(reasons)}）` })\n  }\n\n  // G1 退回 brightness>0 判定（亮度 0 直接算熄屏——老写法）\n  check('G1 退回 brightness>0 判定', () => screenGateInvariants(tamper(REAL.appdel,\n    '  if (UIScreen.mainScreen.brightness > 0) return NO;\\n  return LXLastNonZeroBrightness >= LXScreenOffTrustBrightness;',\n    '  return UIScreen.mainScreen.brightness <= 0;')),\n  '熄屏判定未用「最近非零亮度」证据')\n\n  // G2 阈值归零（亮度 0 只要有任意历史证据就算熄屏）\n  check('G2 阈值归零', () => screenGateInvariants(tamper(REAL.appdel,\n    'static const double LXScreenOffTrustBrightness = 0.3;',\n    'static const double LXScreenOffTrustBrightness = 0;')),\n  '低于 0.2')\n\n  // G3 去掉证据记录（两处都拆：硬关屏与回前台都拿不到依据）\n  check('G3 去掉证据记录', () => {\n    const s = REAL.appdel.replace(/LXRememberScreenBrightness\\(\\);/g, '')\n    if (s === REAL.appdel) throw new Error('tamper 锚点未命中: LXRememberScreenBrightness() 调用')\n    return screenGateInvariants(s)\n  }, '亮度证据的调用点是 0 处')\n\n  return results\n}\n\n// ---------------------------------------------------------------------------\n// 「减发热：后台不做无意义唤醒」三闸门（第 33 轮第 1 条，2026-10-08）\n//\n// 这三处周期性 JS 工作单次都不重，重的是「后台每 N 秒把 CPU 从深度睡眠里拽起来一次」：\n//   ① 倒计时到点退出（playDetail 的 timeoutExit）的 1s UI tick：每秒 callHooks → 订阅者\n//      setState，而后台根本看不见这个数字；到点退出由 BackgroundTimer 保证，与 UI 无关。\n//   ② 首页 pager 横滑自愈心跳：每拍两次跨桥（setScrollEnabled + clearNativePagerScrolling），\n//      后台没有新手势会话、原生也不会产生新的失配。\n//   ③ 网易登录 WebView 的 cookie 轮询：每 1.5s 向不可见的 WebView 注入 JS 取 document.cookie。\n// 三条共同口径「闸门 ≠ 停表」：定时器保留（普通 setInterval → 系统冻结 = 零唤醒零断言），\n// body 首行早退，回前台自动恢复。功能性计时（BackgroundTimer 到点退出、回前台两处自愈\n// 兜底）一条都不许删 —— 所以下面是成对断言。\n// ---------------------------------------------------------------------------\n\nconst HEAT_GATE_FILES = {\n  timeoutExit: 'src/core/player/timeoutExit.ts',\n  main: 'src/screens/Home/Vertical/Main.tsx',\n  webLogin: 'src/components/WebLoginModal.tsx',\n}\n\nconst readHeat = (over = {}) => {\n  const files = {}\n  for (const [k, p] of Object.entries(HEAT_GATE_FILES)) files[k] = over[k] ?? read(p)\n  return files\n}\n\nconst FOREGROUND_GATE = /AppState\\.currentState\\s*!==\\s*'active'/\n\nconst heatGateInvariants = (files) => {\n  const reasons = []\n\n  // ① 倒计时：UI tick 进后台就停刷，但到点退出仍由 BackgroundTimer 独立保证\n  const te = stripComments(files.timeoutExit)\n  const tickAt = te.indexOf('this.timeout = setInterval(() => {')\n  if (tickAt < 0) {\n    reasons.push('timeoutExit 找不到倒计时 1s tick 起表点（闸门无从判定）')\n  } else {\n    const tick = te.slice(tickAt, te.indexOf('}, 1000)', tickAt))\n    if (!FOREGROUND_GATE.test(tick)) {\n      reasons.push('倒计时 1s tick 无前台闸门（后台每秒 callHooks + 订阅者 setState，看不见还照刷）')\n    }\n    if (tick.includes('this.exit()')) {\n      reasons.push('退出动作挪进了受闸门的 UI tick（后台到点就永远不退出 = 省电省出老 bug）')\n    }\n  }\n  if (!/this\\.bgTimeout = BackgroundTimer\\.setTimeout\\(/.test(te)) {\n    reasons.push('倒计时到点不用 BackgroundTimer.setTimeout（普通 setTimeout 后台被冻结 ⇒ 到点不退出）')\n  } else if (!/this\\.bgTimeout = BackgroundTimer\\.setTimeout\\(\\(\\) => \\{[\\s\\S]{0,160}?this\\.exit\\(\\)/.test(te)) {\n    reasons.push('BackgroundTimer 回调里不再 exit（到点退出与 UI tick 的前台闸门必须彼此独立）')\n  }\n\n  // ② 首页横滑自愈心跳：后台不跨桥重发，回前台两处兜底必须还在\n  const main = stripComments(files.main)\n  const hbAt = main.indexOf('const heartbeat = () => {')\n  if (hbAt < 0) {\n    reasons.push('Main.tsx 找不到横滑自愈心跳（心跳没了＝原生闩锁失配只能等下一次真实手势自愈）')\n  } else {\n    const hb = main.slice(hbAt, main.indexOf('const timer = setInterval(heartbeat', hbAt))\n    if (!FOREGROUND_GATE.test(hb)) {\n      reasons.push('横滑心跳无前台闸门（后台每拍两次跨桥：setScrollEnabled + clearNativePagerScrolling）')\n    }\n    if (!hb.includes('resyncPagerScroll()') || !hb.includes('healPagerScrollLatch()')) {\n      reasons.push('心跳少了一次重发或一次闩锁清理（心跳只剩空转，自愈覆盖面缩水）')\n    }\n  }\n  const subAt = main.indexOf(\"AppState.addEventListener('change'\")\n  if (subAt < 0) {\n    reasons.push('Main.tsx 无 AppState 订阅（回前台自愈兜底缺失）')\n  } else {\n    const sub = main.slice(subAt, subAt + 400)\n    if (!sub.includes('clearNativePagerScrolling()') || !sub.includes('resyncPagerScroll()')) {\n      reasons.push('Main.tsx 回前台兜底被削（后台不做 + 回前台也不补 = 横滑开关可能整场失配）')\n    }\n  }\n\n  // ③ 登录 cookie 轮询：后台不注入，但定时器必须活着（回前台自动继续）\n  const wl = stripComments(files.webLogin)\n  const pollAt = wl.indexOf('pollingIntervalRef.current = setInterval(() => {')\n  if (pollAt < 0) {\n    reasons.push('WebLoginModal 找不到 cookie 轮询起表点（闸门无从判定）')\n  } else {\n    const poll = wl.slice(pollAt, wl.indexOf('}, 1500)', pollAt))\n    if (!FOREGROUND_GATE.test(poll)) {\n      reasons.push('cookie 轮询无前台闸门（后台每 1.5s 向不可见的 WebView 注入 JS 取 cookie）')\n    }\n    if (poll.includes('stopPolling')) {\n      reasons.push('cookie 轮询在后台步骤里销毁了定时器（闸门必须是「保留定时器 + body 早退」，回前台要能自动继续）')\n    }\n    if (!poll.includes('loggedInRef.current || isCheckingRef.current')) {\n      reasons.push('cookie 轮询缺重入/完成守卫（省电不该顺手删掉原有守卫）')\n    }\n    if (!poll.includes('injectJavaScript')) {\n      reasons.push('cookie 轮询不再注入取 cookie 的 JS（省电不能把功能省掉）')\n    }\n  }\n  return reasons\n}\n\n// ---------------------------------------------------------------------------\n// 冗余清理（第 33 轮第 1 条「去除冗余代码无用代码」）\n//   三向钉住：① 删除清单（36 条路径 / 52 个文件）不许回潮；\n//            ② 正向对照（活文件必须判为存在，避免路径口径错位后静默全过）；\n//            ③ 全量 import 解析扫描（删过头的唯一真危险；本机无 tsc/eslint，只有它拦得住）。\n// ---------------------------------------------------------------------------\n\nconst R33_REMOVED = [\n  'src/components/KgVerifyModal.tsx',\n  'src/components/YouTubeLoginModal.tsx',\n  'src/components/YouTubeLoginManager.tsx',\n  'src/components/common/Card.tsx',\n  'src/components/common/MediaCard.tsx',\n  'src/components/common/ScaledImage.tsx',\n  'src/components/common/DrawerLayoutFixed.tsx',\n  'src/components/common/DrawerLayoutFixed.ios.tsx',\n  'src/components/common/DorpDownPanel',\n  'src/components/home/AnnouncementCard.tsx',\n  'src/components/home/CategoryChips.tsx',\n  'src/components/home/HorizontalShelf.tsx',\n  'src/components/home/HotSongList.tsx',\n  'src/screens/PlayDetail/components/lyricText.ts',\n  'src/screens/PlayDetail/Vertical/components/TimeoutExitBtn.tsx',\n  'src/screens/PlayDetail/Vertical/components/Btn.tsx',\n  'src/screens/PlayDetail/Vertical/components/Marquee.tsx',\n  'src/screens/PlayDetail/Vertical/Player/components/MoreBtn',\n  'src/screens/Home/Views/Setting/Horizontal/index.tsx',\n  'src/screens/Home/Views/Setting/Vertical/Header.tsx',\n  'src/screens/Home/Views/Setting/settings/Player/IsShowNotificationImage.tsx',\n  'src/screens/Home/Views/Setting/settings/Player/UseNativeFlacPlayer.tsx',\n  'src/utils/nativeModules/cryptoTest.ts',\n  'src/utils/nativeModules/userApiFallback.ts',\n  'src/utils/musicSdk/xm.js',\n  'src/utils/musicSdk/kg/singer.js',\n  'src/utils/musicSdk/mg/album.js',\n  'src/utils/musicSdk/kg/tipSearch.js',\n  'src/utils/musicSdk/mg/tipSearch.js',\n  'src/utils/musicSdk/wy/tipSearch.js',\n  'src/utils/musicSdk/tx/tipSearch.js',\n  'src/utils/musicSdk/bd',\n  'src/utils/musicSdk/yt',\n  'src/utils/musicSdk/kg/temp',\n  'src/utils/musicSdk/mg/temp',\n  'src/utils/musicSdk/tx/qrc',\n]\n\nconst KEEP_CONTROLS = [\n  'src/screens/Home/Vertical/Main.tsx',\n  'src/utils/musicSdk/wy/user.js',\n  'src/screens/Home/Views/DailyRec/index.tsx',\n]\n\nconst redundancyInvariants = (exists) => {\n  const reasons = []\n\n  for (const p of KEEP_CONTROLS) {\n    if (!exists(p)) {\n      reasons.push(`正向对照失败：${p} 判为不存在（清理清单的「不存在」判定不可信，路径口径错位）`)\n    }\n  }\n  for (const p of R33_REMOVED) {\n    if (exists(p)) {\n      reasons.push(`第 33 轮删掉的冗余路径又回来了：${p}（无引用副本不该被拷回；若确需恢复，请连同引用点一起补测试与说明）`)\n    }\n  }\n  return reasons\n}\n\n/** src/ 下全部 JS/TS 源码（相对 ROOT 的 posix 路径 → 源码）。\n *  注意：不能用 readdirSync(dir, { withFileTypes: true }) 的 Dirent.isDirectory() ——\n *  本机契约运行器把工程挂到虚拟根（__dirname === '/scripts'）时，该判定会把文件也报成\n *  目录（app.ts 被判为目录），于是递归进文件里再 readdir 直接 ENOENT。改用\n *  「readdir 成功即目录、抛错即文件」，只依赖 readdirSync 对文件必然抛错这一条标准行为。 */\nconst walkSrcFiles = (dir, out = {}) => {\n  let names\n  try {\n    names = fs.readdirSync(dir)\n  } catch (e) {\n    return out\n  }\n  for (const raw of names) {\n    const name = typeof raw == 'string' ? raw : raw.name\n    if (!name || name === 'node_modules' || name.startsWith('.')) continue\n    const full = path.join(dir, name)\n    let isDir = false\n    try {\n      fs.readdirSync(full)\n      isDir = true\n    } catch (e) {\n      isDir = false\n    }\n    if (isDir) walkSrcFiles(full, out)\n    else if (/\\.(ts|tsx|js|jsx)$/.test(name)) {\n      out[path.relative(ROOT, full).split(path.sep).join('/')] = fs.readFileSync(full, 'utf8')\n    }\n  }\n  return out\n}\n\nconst SRC_MAP = walkSrcFiles(path.join(ROOT, 'src'))\nconst SRC_EXT = ['.ts', '.tsx', '.js', '.jsx', '.json']\nconst SPEC_RE = /(?:from\\s*|require\\s*\\(\\s*|import\\s*\\(\\s*)['\"]([^'\"]+)['\"]/g\n\n// 自制 posix 解析（契约运行器里没有 path.posix）：\n//   'src/plugins/player' + '../utils' → 'src/plugins/utils'\nconst posixResolve = (fromFile, spec) => {\n  const base = fromFile.split('/').slice(0, -1)\n  const out = []\n  for (const seg of base.concat(spec.split('/'))) {\n    if (seg === '' || seg === '.') continue\n    if (seg === '..') { out.pop(); continue }\n    out.push(seg)\n  }\n  return out.join('/')\n}\n\nconst danglingImportInvariants = (exists, files) => {\n  const reasons = []\n  let unresolved = 0\n  for (const [rel, src] of Object.entries(files)) {\n    const code = stripComments(src)\n    SPEC_RE.lastIndex = 0\n    let m\n    while ((m = SPEC_RE.exec(code)) !== null) {\n      const spec = m[1]\n      let base\n      if (spec.startsWith('@/')) base = 'src/' + spec.slice(2)\n      else if (spec.startsWith('./') || spec.startsWith('../')) base = posixResolve(rel, spec)\n      else continue // 裸模块名（node_modules / 原生包）：不归本契约管\n      const cands = [base]\n      for (const e of SRC_EXT) cands.push(base + e)\n      for (const e of SRC_EXT) cands.push(base + '/index' + e)\n      if (!cands.some(p => exists(p))) {\n        unresolved++\n        if (unresolved <= 20) {\n          reasons.push(`${rel} 的 import 指向不存在的文件：'${spec}'（删过头 / 路径写错；本机无 tsc/eslint，只有这道扫描拦得住）`)\n        }\n      }\n    }\n  }\n  if (unresolved > 20) reasons.push(`另有 ${unresolved - 20} 处悬空 import 未逐条列出（先修上面这些）`)\n  return reasons\n}\n\nconst REAL_EXISTS = (rel) => fs.existsSync(path.join(ROOT, rel))\n\nconst runHeatCounterExamples = () => {\n  const results = []\n  const check = (name, fn, expectSubstr) => {\n    let reasons = []\n    try {\n      reasons = fn()\n    } catch (e) {\n      results.push({ name, ok: false, detail: `抛异常: ${e.message}` })\n      return\n    }\n    const hit = reasons.some(r => r.includes(expectSubstr))\n    results.push({ name, ok: hit, detail: hit ? '已拦下' : `未拦下（reasons=${JSON.stringify(reasons)}）` })\n  }\n  const heat = (over) => heatGateInvariants(readHeat(over))\n  const REAL_HEAT = readHeat()\n\n  // H1 倒计时 UI tick 去掉前台闸门（后台每秒刷看不见的数字）\n  check('H1 倒计时 tick 无前台闸门', () => heat({\n    timeoutExit: tamper(REAL_HEAT.timeoutExit, \"      if (AppState.currentState !== 'active') return\\n\", ''),\n  }), '倒计时 1s tick 无前台闸门')\n\n  // H2 到点退出的 BackgroundTimer 被削（省电省成「后台不退出」）\n  check('H2 到点退出不再由 BackgroundTimer 保证', () => heat({\n    timeoutExit: tamper(REAL_HEAT.timeoutExit,\n      '    this.bgTimeout = BackgroundTimer.setTimeout(() => {\\n      this.clearTimer()\\n      this.exit()\\n    }, time * 1000)',\n      '    this.bgTimeout = BackgroundTimer.setTimeout(() => {\\n      this.clearTimer()\\n    }, time * 1000)'),\n  }), '不再 exit')\n\n  // H3 横滑心跳去掉前台闸门（后台每拍两次跨桥）\n  check('H3 横滑心跳无前台闸门', () => heat({\n    main: tamper(REAL_HEAT.main, \"      if (AppState.currentState !== 'active') return\\n      resyncPagerScroll()\", '      resyncPagerScroll()'),\n  }), '横滑心跳无前台闸门')\n\n  // H4 回前台兜底被削（后台不做 + 回前台也不补）\n  check('H4 回前台兜底被削', () => heat({\n    main: tamper(REAL_HEAT.main, '      clearNativePagerScrolling()\\n      resyncPagerScroll()', '      resyncPagerScroll()'),\n  }), '回前台兜底被削')\n\n  // H5 cookie 轮询去掉前台闸门（后台每 1.5s 注入不可见 WebView）\n  check('H5 cookie 轮询无前台闸门', () => heat({\n    webLogin: tamper(REAL_HEAT.webLogin, \"      if (AppState.currentState !== 'active') return\\n\", ''),\n  }), 'cookie 轮询无前台闸门')\n\n  // H6 把闸门写成「停表」（退后台销毁定时器 ⇒ 回前台不再自动继续）\n  check('H6 闸门写成停表', () => heat({\n    webLogin: tamper(REAL_HEAT.webLogin,\n      \"      if (AppState.currentState !== 'active') return\\n      if (loggedInRef.current || isCheckingRef.current) return\",\n      \"      if (AppState.currentState !== 'active') return stopPolling()\\n      if (loggedInRef.current || isCheckingRef.current) return\"),\n  }), '销毁了定时器')\n\n  // D1 冗余路径回潮\n  check('D1 已删冗余路径回潮', () => redundancyInvariants((rel) => rel === 'src/utils/musicSdk/xm.js' || REAL_EXISTS(rel)),\n    '又回来了')\n\n  // D2 删过头（某文件被删但仍有 import 指向它）\n  check('D2 删过头留下悬空 import', () => danglingImportInvariants((rel) => rel !== 'src/plugins/player/nativeFlac.ts' && REAL_EXISTS(rel), SRC_MAP),\n    '指向不存在的文件')\n\n  // D3 正向对照失效（路径口径错位时不许静默全过）\n  check('D3 正向对照失效', () => redundancyInvariants(() => false),\n    '正向对照失败')\n\n  return results\n}\n\n// ---------------------------------------------------------------------------\n// 主流程\n// ---------------------------------------------------------------------------\n\nconst realNative = nativeInvariants(REAL.appdel)\nconst realJs = jsInvariants(REAL.playProgress)\nconst realPaused = pausedInvariants(readGlass())\nconst realBg = bgInvariants(readBg())\nconst realScreenGate = screenGateInvariants(REAL.appdel)\nconst realHeat = heatGateInvariants(readHeat())\nconst realRedundancy = [...redundancyInvariants(REAL_EXISTS), ...danglingImportInvariants(REAL_EXISTS, SRC_MAP)]\n\nconsole.log('=== sim-power-drain ===')\nconsole.log('\\n[原生 AppDelegate.mm]')\nif (realNative.ok) console.log('  PASS 原生歌词时钟可停 / 无热路径 NSLog / 周期契约')\nelse realNative.reasons.forEach(r => console.log('  FAIL ' + r))\n\nconsole.log('\\n[JS playProgress.ts]')\nif (realJs.ok) console.log('  PASS 后台守卫齐备')\nelse realJs.reasons.forEach(r => console.log('  FAIL ' + r))\n\nconsole.log('\\n[玻璃覆盖暂停链路（前台省电）]')\nif (realPaused.length === 0) console.log('  PASS paused 链路 8 文件贯通（EffectView/manager/组件/消费点/hook/图标）')\nelse realPaused.forEach(r => console.log('  FAIL ' + r))\n\nconsole.log('\\n[后台不可见即停（2026-10-02 用户第 8 条）]')\nif (realBg.length === 0) {\n  console.log('  PASS Tab 栏两块玻璃前台门 + 迷你条玻璃与 useMemo 依赖 + 缓冲轮询起表收敛/前后台订阅 + 下载进度限流')\n} else {\n  realBg.forEach(r => console.log('  FAIL ' + r))\n}\n\nconsole.log('\\n[亮度证据熄屏门（第 23 轮）]')\nif (realScreenGate.length === 0) {\n  console.log('  PASS 亮度 0 走「最近非零亮度」证据 + 阈值 ≥0.2 + 记录先于判定 + 两处取证 + 统一守卫消费')\n} else {\n  realScreenGate.forEach(r => console.log('  FAIL ' + r))\n}\n\nconsole.log('\\n[减发热：后台不做无意义唤醒三闸门（第 33 轮第 1 条）]')\nif (realHeat.length === 0) {\n  console.log('  PASS 倒计时 UI tick / 横滑自愈心跳 / 登录 cookie 轮询：闸门在、定时器保留、功能计时与回前台兜底一条没少')\n} else {\n  realHeat.forEach(r => console.log('  FAIL ' + r))\n}\n\nconsole.log('\\n[冗余清理（第 33 轮第 1 条）]')\nif (realRedundancy.length === 0) {\n  console.log(`  PASS 删除清单 ${R33_REMOVED.length} 条路径全不存在 + ${KEEP_CONTROLS.length} 项正向对照 + ${Object.keys(SRC_MAP).length} 个源文件 import 全解析`)\n} else {\n  realRedundancy.forEach(r => console.log('  FAIL ' + r))\n}\n\nconsole.log('\\n[反例自检]')\nconst ceResults = runCounterExamples()\nconst peResults = runPausedCounterExamples()\nconst beResults = runBgCounterExamples()\nconst sgResults = runScreenGateCounterExamples()\nconst hResults = runHeatCounterExamples()\nlet ceAllOk = true\nconst allResults = [...ceResults, ...peResults, ...beResults, ...sgResults, ...hResults]\nfor (const r of allResults) {\n  console.log(`  ${r.ok ? 'PASS' : 'FAIL'} ${r.name} —— ${r.ok ? '已拦下' : `未拦下（reasons=${JSON.stringify(r.detail)}）`}`)\n  if (!r.ok) ceAllOk = false\n}\n\nconst invCount = [realNative.ok, realJs.ok, realPaused.length === 0, realBg.length === 0, realScreenGate.length === 0, realHeat.length === 0, realRedundancy.length === 0].filter(Boolean).length\nconst allOk = invCount === 7 && ceAllOk\nconsole.log(`\\n结果：${allOk ? 'ALL PASS' : '有失败项'}（不变量 ${allOk || invCount > 0 ? `${invCount}/7` : '0/7'}；反例 ${allResults.filter(r => r.ok).length}/${allResults.length}）`)\nprocess.exit(allOk ? 0 : 1)\n" },
  { n: "sim-heat-idle-gates.js", s: "/**\n * sim-heat-idle-gates.js\n *\n * 第 57 轮「长时间使用发烫 / 不播放音乐留在后台也发烫」的降载闸门契约 + 死代码清除契约。\n *\n * 用户原话（第 57 轮）：「不播放音乐时，减少占用导致的发热，播放音乐时，优化代码，\n * 去除冗余代码，尽量减少代码中的注释，总之减少发热……前提是不要影响目前所有的功能和展示样式。」\n *\n * 三条闸门（都在 ios/LxMusicMobile/AppDelegate.mm）：\n *   A 前台位置事件从 20Hz 节流到 250ms（4Hz）。原先是歌词时钟每一拍都往 JS 发一次位置\n *     （桥接 → JS 处理器 → store 派发 → 进度组件重渲染），是本轮「播放时」发热的主力。\n *     闸门行保持原样、节流**单独嵌套一层**：那一行是 sim-remote-command-lockscreen-tap 的\n *     g7 反例与 sim-nowplaying-lyric-arbitration ⑥ 逐字钉住的锚点，换行即锚点漂移。\n *   B 暂停期间的缓冲轮询从 30ms 放宽到 200ms —— 暂停挂着时唯一还在高频转的轮询。\n *   C stop（真停播）之后、且「图已拆干净」时释放音频会话。会话是后台执行权的凭证\n *     （Info.plist 的 UIBackgroundModes=audio），不释放则「不播放留后台」时进程照旧活着：\n *     JS 定时器、桥接、存活检查全部继续跑。pause 不动（第 48 轮定案：锁屏卡片 / 遥控按键\n *     要靠常驻会话），reset 不动（JS 拿它当「换引擎前的清场」，紧随其后就是另一台引擎起播）。\n *\n * 死代码清除：逐点钉住本轮删掉的「注释掉的死代码」不许回来（代表点），以及 pannerTimer\n * 定时器家族（属性 / 创建 / 取消）整族不许回来。\n *\n * 运行：node scripts/sim-heat-idle-gates.js\n * 退出码：不变量全过、且全部反例被拦下时为 0，否则 1。\n */\n\n'use strict'\n\nconst fs = require('fs')\nconst path = require('path')\n\nconst ROOT = path.join(__dirname, '..')\nconst read = (p) => fs.readFileSync(path.join(ROOT, p), 'utf8').replace(/\\r\\n/g, '\\n')\n\nconst APP_DELEGATE = 'ios/LxMusicMobile/AppDelegate.mm'\nconst PLAYER_UTILS = 'src/plugins/player/utils.ts'\nconst PLAYER_HOOK = 'src/plugins/player/hook.ts'\nconst PLAYER_PLAYLIST = 'src/plugins/player/playList.ts'\nconst COMMON_TEXT = 'src/components/common/Text.tsx'\nconst COMMON_INPUT = 'src/components/common/Input.tsx'\nconst THEMES_INDEX = 'src/theme/themes/index.ts'\nconst SEARCH_ACTION = 'src/store/search/action.ts'\n\nconst REAL_APPDELEGATE = read(APP_DELEGATE)\nconst REAL_UTILS = read(PLAYER_UTILS)\nconst REAL_HOOK = read(PLAYER_HOOK)\nconst REAL_PLAYLIST = read(PLAYER_PLAYLIST)\nconst REAL_TEXT = read(COMMON_TEXT)\nconst REAL_INPUT = read(COMMON_INPUT)\nconst REAL_THEMES = read(THEMES_INDEX)\nconst REAL_SEARCH = read(SEARCH_ACTION)\n\nconst stripComments = (src) =>\n  src.replace(/\\/\\*[\\s\\S]*?\\*\\//g, '').replace(/\\/\\/[^\\n]*/g, '')\n\n/** 从源码抽出「以 signature 开头、后接大括号体」的函数体（按大括号配平）。 */\nconst extractBracedBody = (src, signature) => {\n  let start = src.indexOf(signature)\n  while (start >= 0) {\n    const after = src.slice(start + signature.length)\n    if (/^\\s*\\{/.test(after)) {\n      const braceStart = start + signature.length + after.indexOf('{')\n      let depth = 0\n      for (let i = braceStart; i < src.length; i++) {\n        const ch = src[i]\n        if (ch === '{') depth++\n        else if (ch === '}') {\n          depth--\n          if (depth === 0) return src.slice(start, i + 1)\n        }\n      }\n      return null\n    }\n    start = src.indexOf(signature, start + 1)\n  }\n  return null\n}\n\n// ---------------------------------------------------------------------------\n// A. 前台位置事件 4Hz 节流\n// ---------------------------------------------------------------------------\n\nconst POSITION_GATE =\n  'if (!paused && [UIApplication sharedApplication].applicationState == UIApplicationStateActive) {'\nconst POSITION_THROTTLE = 'elapsedRefreshNowMs - LXNowPlayingPositionBroadcastAtMs >= 250.0'\nconst POSITION_THROTTLE_RE = /elapsedRefreshNowMs - LXNowPlayingPositionBroadcastAtMs >= ([0-9.]+)/\nconst POSITION_STAMP = 'LXNowPlayingPositionBroadcastAtMs = elapsedRefreshNowMs;'\nconst POSITION_POST = 'postNotificationName:LXPlayerPositionNotificationName'\nconst POSITION_DECL = 'static double LXNowPlayingPositionBroadcastAtMs = 0;'\nconst EARLY_RETURN_NO_LYRIC = 'if (LXNowPlayingLyricLines.count == 0) return;'\n\nconst positionThrottleInvariants = (raw) => {\n  const reasons = []\n  const code = stripComments(raw)\n  const step = extractBracedBody(raw, 'static void LXNowPlayingLyricStep(void)')\n  if (!step) {\n    reasons.push('LXNowPlayingLyricStep 缺失或抽取失败（锚点漂移）')\n    return reasons\n  }\n  const body = stripComments(step)\n\n  // ① 时钟戳只许一处声明、只许一处写入（多处 = 有人另起了一条位置广播旁路）\n  const decls = code.match(/static double LXNowPlayingPositionBroadcastAtMs = 0;/g) || []\n  if (decls.length !== 1) {\n    reasons.push(`LXNowPlayingPositionBroadcastAtMs 声明 ${decls.length} 处（应恰好一处 —— 多出来的每一处都是绕过 4Hz 节流的旁路）`)\n  }\n  const inStep = (body.match(/LXNowPlayingPositionBroadcastAtMs/g) || []).length\n  const inFile = (code.match(/LXNowPlayingPositionBroadcastAtMs/g) || []).length\n  if (inFile !== inStep + 1) {\n    reasons.push(`LXNowPlayingPositionBroadcastAtMs 在时钟函数之外还有 ${inFile - inStep - 1} 处引用（位置广播只许留在 LXNowPlayingLyricStep 里）`)\n  }\n  const stamps = (body.match(/LXNowPlayingPositionBroadcastAtMs = elapsedRefreshNowMs;/g) || []).length\n  if (stamps !== 1) {\n    reasons.push(`位置广播的时间戳写入 ${stamps} 处（应恰好一处、且与广播同拍 —— 判据读的就是它：不写回时间戳，第二拍起判据永远成立不了，进度条会冻在第一拍）`)\n  }\n\n  // ② 节流判据必须在、档位必须是 250ms\n  const throttleMatch = POSITION_THROTTLE_RE.exec(body)\n  if (throttleMatch == null) {\n    reasons.push(`前台位置事件没有 4Hz 节流（缺 \\`${POSITION_THROTTLE}\\` —— 歌词时钟 20Hz，每一拍都发就等于 20Hz 桥接事件：桥接 → JS 处理器 → store 派发 → 进度组件重渲染，第 57 轮的降发热口径当场作废）`)\n  } else if (Number(throttleMatch[1]) !== 250) {\n    reasons.push(`位置事件节流档位被改成 ${throttleMatch[1]}ms（第 57 轮契约值 250ms —— 与 JS 侧既有设计同档：慢校准 1s、seek 收敛 2s、进度条 tick 不挂过渡；改小＝桥接次数回升、发热回归，改大＝进度条肉眼可见地一格一格跳）`)\n  }\n\n  // ③ 形状：节流嵌在前台闸门里、在广播之前；闸门行本身不许改写\n  const iGate = body.indexOf(POSITION_GATE)\n  const iThrottle = throttleMatch == null ? -1 : throttleMatch.index\n  const iPost = body.indexOf(POSITION_POST)\n  const iStamp = body.indexOf(POSITION_STAMP)\n  if (iGate < 0) {\n    reasons.push('前台闸门行不见了或被改写（第 57 轮口径：闸门行原样保留、节流单独嵌套一层 —— 那一行是 sim-remote-command-lockscreen-tap 的 g7 反例与 sim-nowplaying-lyric-arbitration ⑥ 逐字钉住的锚点）')\n  } else if (iThrottle >= 0 && iThrottle < iGate) {\n    reasons.push('节流判据落到了「仅前台」闸门之外（后台 / 熄屏时也在判 —— 节流与前台闸门必须同层：闸门里第一句就是节流）')\n  }\n  if (iPost < 0) {\n    reasons.push('位置事件不见了（JS 进度条的前台数据源没了）')\n  } else if (iThrottle >= 0 && iThrottle > iPost) {\n    reasons.push('节流判据落在位置广播之后（判了等于没判，每拍照发）')\n  }\n  if (iStamp >= 0 && iPost >= 0 && iStamp > iPost) {\n    reasons.push('时间戳写在广播之后（先发再记，下一拍的判据从「刚发过」起算，实际间隔被拉长）')\n  }\n\n  // ④ 必须仍在「无歌词早退」之前 —— 没有歌词的歌也要按 4Hz 走进度条\n  const iEarly = body.indexOf(EARLY_RETURN_NO_LYRIC)\n  if (iThrottle >= 0 && iEarly >= 0 && iThrottle > iEarly) {\n    reasons.push('位置事件落在「无歌词早退」之后（没有歌词的歌前台进度条不再更新 —— 这是第 46 轮就修过的老坑）')\n  }\n\n  return reasons\n}\n\n// ---------------------------------------------------------------------------\n// B. 暂停期间的缓冲轮询放宽到 200ms\n// ---------------------------------------------------------------------------\n\nconst PAUSED_POLL = '[NSThread sleepForTimeInterval:self.manualPause ? 0.2 : 0.03];'\n\nconst pausedPollInvariants = (raw) => {\n  const reasons = []\n  const body = extractBracedBody(raw, '- (void)waitForBufferCapacityIfNeeded')\n  if (!body) {\n    reasons.push('waitForBufferCapacityIfNeeded 缺失或抽取失败（锚点漂移）')\n    return reasons\n  }\n  const code = stripComments(body)\n\n  if (!code.includes('while (!self.stopRequested && !self.seekRequested)')) {\n    reasons.push('缓冲等待循环不见了（stopRequested / seekRequested 守卫没了，这条空转轮询会一直转下去）')\n  }\n  if (!code.includes(PAUSED_POLL)) {\n    const m = /\\[NSThread sleepForTimeInterval:[^\\]]*\\]/.exec(code)\n    reasons.push(`暂停期间的缓冲轮询不是 200ms（第 57 轮口径：手动暂停时从 33Hz（30ms）放宽到 5Hz（200ms） —— 暂停期间环里已存着 pausedBufferSeconds 的音频，最坏 200ms 才补货，听感无差异；当前原文：${m ? m[0] : '（找不到 sleepForTimeInterval）'}）`)\n  }\n  const iBreak = code.indexOf('if (!shouldWait) break;')\n  const iSleep = code.indexOf('[NSThread sleepForTimeInterval:')\n  if (iBreak >= 0 && iSleep >= 0 && iSleep < iBreak) {\n    reasons.push('睡眠落在「不需要等就跳出」之前（不需要等待时也会先睡一觉，反而拖慢正常起播）')\n  }\n  return reasons\n}\n\n// ---------------------------------------------------------------------------\n// C. stop 之后释放音频会话（幂等守卫 + 调用点唯一）\n// ---------------------------------------------------------------------------\n\nconst RELEASE_CALL = '[self releaseAudioSessionWhenIdle];'\nconst RELEASE_GUARD = 'if (self.engine != nil || self.sourceNode != nil) return;'\nconst STOP_SIGNATURE =\n  'RCT_REMAP_METHOD(stop, stopStreamWithResolver:(RCTPromiseResolveBlock)resolve rejecter:(RCTPromiseRejectBlock)reject)'\nconst RESET_SIGNATURE =\n  'RCT_REMAP_METHOD(reset, resetStreamWithResolver:(RCTPromiseResolveBlock)resolve rejecter:(RCTPromiseRejectBlock)reject)'\nconst STOP_INTERNAL_SIGNATURE = '- (void)stopStreamingInternal:(BOOL)resetAudio'\n\nconst releaseWhenIdleInvariants = (raw) => {\n  const reasons = []\n  const code = stripComments(raw)\n\n  // ① 定义 + 幂等守卫 + 真的 setActive:NO\n  const def = extractBracedBody(raw, '- (void)releaseAudioSessionWhenIdle')\n  if (!def) {\n    reasons.push('releaseAudioSessionWhenIdle 定义缺失（「不播放留后台」将重新持有会话：进程不被挂起，JS 定时器 / 桥接 / 存活检查照旧跑，正是用户第 57 轮报的「不播放音乐留在后台也会很烫」）')\n  } else {\n    const body = stripComments(def)\n    if (!body.includes(RELEASE_GUARD)) {\n      reasons.push(`释放会话前没有「图已拆干净」的守卫（缺 \\`${RELEASE_GUARD}\\` —— 引擎 / 源节点还在时释放会当场静音：这是本轮唯一会「一放就没声」的写法）`)\n    }\n    if (!/\\[session setActive:NO/.test(body)) {\n      reasons.push('释放函数里没有 setActive:NO（会话根本没让出，等于什么都没做）')\n    }\n  }\n\n  // ② 调用点唯一，且在 stop 里、排在 stopStreamingInternal 之后\n  const calls = (code.match(/\\[self releaseAudioSessionWhenIdle\\];/g) || []).length\n  if (calls !== 1) {\n    reasons.push(`释放会话的调用点 ${calls} 处（应恰好一处：只有 stop 释放 —— pause 释放会让锁屏卡片变灰、遥控按键与进度条拖动全失效（第 48 轮定案）；reset 释放会在「换引擎前的清场」里把紧随其后的起播挡掉）`)\n  }\n  const stop = extractBracedBody(raw, STOP_SIGNATURE)\n  if (!stop) {\n    reasons.push('RCT_REMAP_METHOD(stop, ...) 缺失或抽取失败（锚点漂移）')\n  } else {\n    const body = stripComments(stop)\n    const iInner = body.indexOf('[self stopStreamingInternal:YES];')\n    const iRelease = body.indexOf(RELEASE_CALL)\n    if (iRelease < 0) {\n      reasons.push('stop 里不再释放音频会话（「不播放留后台」的发热成因就回来了）')\n    } else if (iInner >= 0 && iRelease < iInner) {\n      reasons.push('释放排在 stopStreamingInternal 之前（图还没拆就判「引擎 / 源节点是否为空」—— 判据必须排在拆图之后）')\n    }\n  }\n\n  // ③ 不许塞进 stopStreamingInternal（openStream 会先激活会话再调它 ⇒ 起播瞬间被释放）\n  const internal = extractBracedBody(raw, STOP_INTERNAL_SIGNATURE)\n  if (internal && stripComments(internal).includes('releaseAudioSessionWhenIdle')) {\n    reasons.push('释放会话被塞进了 stopStreamingInternal —— openStream 的顺序是「先 prepareAudioSession（setActive:YES）再 stopStreamingInternal」，塞进来就会在起播瞬间把刚激活的会话释放掉（直接无声）')\n  }\n  // ④ 不许塞进 reset（JS 把 reset 当换引擎前的清场）\n  const reset = extractBracedBody(raw, RESET_SIGNATURE)\n  if (reset && stripComments(reset).includes('releaseAudioSessionWhenIdle')) {\n    reasons.push('reset 里也释放了音频会话 —— JS 侧把 reset 当「换引擎前的清场」（nativeFlac → AVPlayer 兜底、startNativeFlacPlayback 开场），紧随其后就是另一台引擎起播：在这里让出会话等于给起播挖坑')\n  }\n  return reasons\n}\n\n// ---------------------------------------------------------------------------\n// D. 死代码清除（本轮删掉的注释代码不许回来）\n// ---------------------------------------------------------------------------\n\n// [文件, 原文, 回归标志（任一命中即回归）, 为什么会回来 = 回归后果]\n// 注意：这里**不能** stripComments —— 要拦的正是「注释掉的死代码又贴回来」，\n// 所以标志串都取「只在代码里出现、不会出现在说明性注释里」的形状。\nconst DEAD_CODE_GONE = [\n  [APP_DELEGATE, REAL_APPDELEGATE, ['self.pannerTimer', 'dispatch_source_t pannerTimer'],\n    'pannerTimer 定时器家族（属性 / 创建 / 取消）第 57 轮已整族删除：声像摆动早已改由 _realtimePannerProcessor 在渲染回调里做，那个 dispatch_source 没有任何创建点，只留下「取消一个永远是 nil 的定时器」'],\n  [PLAYER_UTILS, REAL_UTILS, ['debouncePlayMusicTools'],\n    'debouncePlayMusicTools（快速切歌去抖的旧实现）已由 playList.ts 的 debounceUpdateMetaInfoTools 取代'],\n  [PLAYER_HOOK, REAL_HOOK, ['useTrackPlayerEvents'],\n    'hook.ts 里的 useTrackPlayerEvents 本地副本已删除（事件订阅走统一漏斗，别再养第二份）'],\n  [PLAYER_PLAYLIST, REAL_PLAYLIST, ['delayUpdateMusicInfo = (('],\n    'playList.ts 里注释掉的旧 delayUpdateMusicInfo 实现已删除（真身是同文件的 debounceUpdateMetaInfoTools.init()）'],\n  [COMMON_TEXT, REAL_TEXT, ['warpText'],\n    'Text.tsx 里注释掉的 warpText 实现已删除'],\n  [COMMON_INPUT, REAL_INPUT, ['showClearBtn'],\n    'Input.tsx 里注释掉的 clear 按钮动画实现已删除'],\n  [THEMES_INDEX, REAL_THEMES, ['copyTheme'],\n    'themes/index.ts 里注释掉的 copyTheme 实现已删除'],\n  [SEARCH_ACTION, REAL_SEARCH, ['isInitedSearchHistory'],\n    'search/action.ts 里注释掉的搜索历史初始化实现已删除'],\n  [APP_DELEGATE, REAL_APPDELEGATE, ['LXStartRemoteCommandWatchdog'],\n    '第 43 轮删掉的 1s 可用性看门狗不许回来（它只重写六个 enabled、不重发 info / playbackState，会把显示态与启停态的分叉钉死）'],\n]\n\n// overrides：反例用「篡改后的原文」替换某个文件的正文（不污染模块级常量）\nconst deadCodeInvariants = (overrides = {}) => {\n  const reasons = []\n  for (const [file, text, patterns, why] of DEAD_CODE_GONE) {\n    const body = file in overrides ? overrides[file] : text\n    const hit = patterns.find(p => body.includes(p))\n    if (hit) {\n      reasons.push(`${file} 里又出现了 \\`${hit}\\` —— ${why}`)\n    }\n  }\n  return reasons\n}\n\n// ---------------------------------------------------------------------------\n// 反例（对篡改后的源码跑同一套判断，必须被拦下）\n// ---------------------------------------------------------------------------\n\nconst tamper = (src, find, replace) => {\n  if (!src.includes(find)) throw new Error(`tamper 锚点未命中: ${find.slice(0, 60)}`)\n  return src.replace(find, replace)\n}\n\nconst POSITION_BLOCK =\n  '      if (elapsedRefreshNowMs - LXNowPlayingPositionBroadcastAtMs >= 250.0) {\\n' +\n  '        LXNowPlayingPositionBroadcastAtMs = elapsedRefreshNowMs;\\n' +\n  '        [[NSNotificationCenter defaultCenter] postNotificationName:LXPlayerPositionNotificationName\\n' +\n  '                                                            object:nil\\n' +\n  '                                                            userInfo:@{ @\"position\": @(positionMs / 1000.0), @\"rate\": @(rate) }];\\n' +\n  '      }\\n'\n\nconst runCounterExamples = () => {\n  const results = []\n  const check = (name, fn, expectReasonSubstr) => {\n    let reasons = []\n    try {\n      reasons = fn()\n    } catch (e) {\n      results.push({ name, ok: false, detail: `抛异常: ${String(e.message).slice(0, 120)}` })\n      return\n    }\n    const hit = reasons.some(r => r.includes(expectReasonSubstr))\n    results.push({ name, ok: hit, detail: hit ? '已拦下' : `未拦下（reasons=${JSON.stringify(reasons)}）` })\n  }\n\n  // ── A 位置事件节流 ──────────────────────────────────────────────────────\n  // p1 节流整块删掉（= 回到第 57 轮之前：每拍 20Hz 都发）→ 报「4Hz 节流」\n  check('p1 前台位置事件回到 20Hz 每拍发', () => positionThrottleInvariants(tamper(REAL_APPDELEGATE,\n    POSITION_BLOCK, ''))\n    , '4Hz 节流')\n\n  // p2 档位缩到 50ms（≈ 每拍都发，节流名存实亡）→ 报「契约值 250ms」\n  check('p2 节流档位被缩到 50ms', () => positionThrottleInvariants(tamper(REAL_APPDELEGATE,\n    'elapsedRefreshNowMs - LXNowPlayingPositionBroadcastAtMs >= 250.0',\n    'elapsedRefreshNowMs - LXNowPlayingPositionBroadcastAtMs >= 50.0'))\n    , '契约值 250ms')\n\n  // p3 判据在、时间戳不写（第二拍起判据永远成立不了 → 进度条冻在第一拍）→ 报「时间戳」\n  check('p3 只判节流不写时间戳', () => positionThrottleInvariants(tamper(REAL_APPDELEGATE,\n    '        LXNowPlayingPositionBroadcastAtMs = elapsedRefreshNowMs;\\n', ''))\n    , '时间戳')\n\n  // p4 节流块被搬到「仅前台」闸门外面（后台 / 熄屏也在判）→ 报「闸门之外」\n  check('p4 节流块被搬到前台闸门之外', () => positionThrottleInvariants(tamper(REAL_APPDELEGATE,\n    '    ' + POSITION_GATE + '\\n' + POSITION_BLOCK,\n    POSITION_BLOCK + '    ' + POSITION_GATE + '\\n'))\n    , '闸门之外')\n\n  // p5 闸门行被改写（把节流并进同一行条件 —— 会让 g7 / ⑥ 的锚点漂移）→ 报「闸门行」\n  check('p5 前台闸门行被改写', () => positionThrottleInvariants(tamper(REAL_APPDELEGATE,\n    POSITION_GATE, 'if (!paused && appActive) {'))\n    , '闸门行')\n\n  // ── B 暂停轮询 ──────────────────────────────────────────────────────────\n  // q1 退回 30ms（暂停挂着时每秒 33 次唤醒）→ 报「200ms」\n  check('q1 暂停轮询退回 30ms', () => pausedPollInvariants(tamper(REAL_APPDELEGATE,\n    PAUSED_POLL, '[NSThread sleepForTimeInterval:0.03];'))\n    , '200ms')\n\n  // ── C stop 释放会话 ────────────────────────────────────────────────────\n  // c1 调用点从 stop 挪进 stopStreamingInternal（openStream 也走它 ⇒ 起播瞬间被释放）→ 报「stopStreamingInternal」\n  check('c1 释放会话被塞进 stopStreamingInternal', () => releaseWhenIdleInvariants(tamper(\n    tamper(REAL_APPDELEGATE, '  [self stopStreamingInternal:YES];\\n  [self releaseAudioSessionWhenIdle];\\n', '  [self stopStreamingInternal:YES];\\n'),\n    STOP_INTERNAL_SIGNATURE + ' {\\n',\n    STOP_INTERNAL_SIGNATURE + ' {\\n  [self releaseAudioSessionWhenIdle];\\n'))\n    , 'stopStreamingInternal')\n\n  // c2 幂等守卫被删（无条件 setActive:NO）→ 报「守卫」\n  check('c2 释放前不判「图是否拆干净」', () => releaseWhenIdleInvariants(tamper(REAL_APPDELEGATE,\n    '  ' + RELEASE_GUARD + '\\n', ''))\n    , '守卫')\n\n  // c3 reset 里也释放一次（换引擎前的清场被让出会话）→ 报「reset」\n  check('c3 reset 里也释放会话', () => releaseWhenIdleInvariants(tamper(REAL_APPDELEGATE,\n    RESET_SIGNATURE, RESET_SIGNATURE + '\\n  [self releaseAudioSessionWhenIdle];\\n'))\n    , 'reset')\n\n  // c4 整个释放函数被删（会话重新常驻）→ 报「定义缺失」\n  check('c4 释放函数被整条删除', () => releaseWhenIdleInvariants(tamper(REAL_APPDELEGATE,\n    '- (void)releaseAudioSessionWhenIdle {\\n  if (self.engine != nil || self.sourceNode != nil) return;\\n  AVAudioSession *session = [AVAudioSession sharedInstance];\\n  [session setActive:NO withOptions:AVAudioSessionSetActiveOptionNotifyOthersOnDeactivation error:nil];\\n}\\n\\n',\n    ''))\n    , '定义缺失')\n\n  // ── D 死代码回流 ───────────────────────────────────────────────────────\n  // d1 pannerTimer 家族回来（属性 / 创建 / 取消任意一处）→ 报「pannerTimer」\n  check('d1 pannerTimer 定时器家族回归', () => deadCodeInvariants({\n    [APP_DELEGATE]: tamper(REAL_APPDELEGATE,\n      '- (void)releaseAudioSessionWhenIdle {',\n      '  self.pannerTimer = nil;\\n- (void)releaseAudioSessionWhenIdle {'),\n  }), 'pannerTimer')\n\n  // d2 注释掉的死代码回来（themes/index.ts 的 copyTheme）→ 报「copyTheme」\n  check('d2 死代码 copyTheme 回流', () => deadCodeInvariants({\n    [THEMES_INDEX]: tamper(REAL_THEMES, 'export const getTheme = async() => {',\n      '// const copyTheme = (id) => {\\n// }\\nexport const getTheme = async() => {'),\n  }), 'copyTheme')\n\n  // d3 第 43 轮删掉的 1s 看门狗回来 → 报「看门狗」\n  check('d3 可用性看门狗回归', () => deadCodeInvariants({\n    [APP_DELEGATE]: tamper(REAL_APPDELEGATE,\n      '- (void)releaseAudioSessionWhenIdle {',\n      '// static void LXStartRemoteCommandWatchdog(void) {\\n//   LXApplyNowPlayingInfo();\\n// }\\n- (void)releaseAudioSessionWhenIdle {'),\n  }), '看门狗')\n\n  return results\n}\n\n// ---------------------------------------------------------------------------\n// 主流程\n// ---------------------------------------------------------------------------\n\nconsole.log('=== sim-heat-idle-gates ===')\n\nconst checks = [\n  ['原生：前台位置事件 4Hz 节流（第 57 轮 A）', () => positionThrottleInvariants(REAL_APPDELEGATE)],\n  ['原生：暂停期间缓冲轮询放宽到 200ms（第 57 轮 B）', () => pausedPollInvariants(REAL_APPDELEGATE)],\n  ['原生：stop 之后在「图已拆干净」时释放音频会话（第 57 轮 C）', () => releaseWhenIdleInvariants(REAL_APPDELEGATE)],\n  ['死代码：已删的注释代码与 pannerTimer 家族不许回来（第 57 轮 D）', () => deadCodeInvariants()],\n]\n\nlet invOk = true\nfor (const [name, fn] of checks) {\n  const reasons = fn()\n  if (reasons.length === 0) {\n    console.log(`\\n[${name}]\\n  PASS`)\n  } else {\n    invOk = false\n    console.log(`\\n[${name}]`)\n    reasons.forEach(r => console.log('  FAIL ' + r))\n  }\n}\n\nconsole.log('\\n[反例自检]')\nconst ceResults = runCounterExamples()\nlet ceAllOk = true\nfor (const r of ceResults) {\n  console.log(`  ${r.ok ? 'PASS' : 'FAIL'} ${r.name} —— ${r.ok ? '已拦下' : `未拦下（${r.detail}）`}`)\n  if (!r.ok) ceAllOk = false\n}\n\nconst allOk = invOk && ceAllOk\nconsole.log(`\\n结果：${allOk ? 'ALL PASS' : '有失败项'}（不变量 ${checks.length}/${checks.length}；反例 ${ceResults.filter(r => r.ok).length}/${ceResults.length}）`)\nprocess.exit(allOk ? 0 : 1)\n" },
]

const fmt = (v) => {
  if (typeof v === 'string') return v
  try { return JSON.stringify(v) } catch (e) { return String(v) }
}

// 与 run.py 的 runner.html 逐字同形的 require 映射（成员平时就是这么跑的）
const makeRequire = () => (name) => {
  if (name === 'fs' || name === 'node:fs') return require('fs')
  if (name === 'path' || name === 'node:path') return require('path')
  if (name === 'os' || name === 'node:os') return { EOL: '\n', platform: () => 'win32', cpus: () => [] }
  if (name === 'child_process' || name === 'node:child_process') return {
    execSync: () => '',
    spawnSync: () => ({ status: 0, stdout: '', stderr: '', error: null }),
    exec: () => ({ on: () => {}, stdout: { on: () => {} }, stderr: { on: () => {} } }),
  }
  if (name === 'util' || name === 'node:util') return { inspect: fmt }
  throw new Error('MODULE_NOT_SUPPORTED: ' + name)
}

// 成员看到的 __dirname / __filename：**拿套件自己的那一份**，两种运行环境下都正确 ——
// 浏览器 runner 里套件作用域的 __dirname 是 '/scripts'（HTTP 根即工程根），
// 真实 node 里是 '<工程根>\scripts'。这里**不能写死** '/scripts'：真实 node 下
// path.resolve('/scripts', '..') 会落到盘根（E:\），成员一律 ENOENT。
const DIRNAME = (typeof __dirname === 'string' && __dirname) ? __dirname : '/scripts'

const RESULTS = []
MEMBERS.forEach((m, i) => {
  const tag = `[${i + 1}/${MEMBERS.length}] ${m.n}`
  console.log(`===== ${tag} =====`)
  const lines = []
  const memberConsole = {
    log: (...a) => lines.push(a.map(fmt).join(' ')),
    error: (...a) => lines.push('[err] ' + a.map(fmt).join(' ')),
    warn: (...a) => lines.push('[warn] ' + a.map(fmt).join(' ')),
  }
  let code = null
  const memberProcess = {
    // runner.html 的 shim 也是「记下退出码，不真的退出」—— 逐字保持同形，
    // 这样「合并前跑一次、合并后跑一次」的输出与退出码才可比
    exit: (c) => { if (code === null) code = (c === undefined ? 0 : c) },
    argv: ['node', 'scripts/' + m.n],
    cwd: () => '/',
    env: {},
    platform: 'win32',
    version: 'v20.11.0',
    versions: { node: '20.11.0' },
  }
  let fatal = null
  try {
    const mod = { exports: {} }
    // 与 runner.html 完全同形的两步预处理：剥掉开头的 BOM 与 shebang
    //（`#!` 不是合法 JS —— 独立跑时由 runner 剥，收进套件后必须由套件自己剥，
    //  否则带 shebang 的成员会当场 SyntaxError），再追加 sourceURL 注释让栈指回成员名
    const src = String(m.s).replace(/^\uFEFF/, '').replace(/^#![^\n]*\r?\n/, '')
    const fn = new Function('require', 'process', 'console', '__dirname', '__filename', 'module', 'exports',
      src + '\n//# sourceURL=scripts/' + m.n)
    fn(makeRequire(), memberProcess, memberConsole, DIRNAME, DIRNAME + '/' + m.n, mod, mod.exports)
  } catch (e) {
    fatal = (e && e.stack) ? e.stack : String(e)
  }
  if (fatal != null) {
    lines.push('[FATAL] ' + fatal)
    if (code === null) code = 1
  }
  for (const l of lines) console.log(l)
  const rc = code === null ? 0 : code
  RESULTS.push({ name: m.n, rc, exited: code !== null })
  console.log(`===== ${tag} → exit ${rc} =====`)
})

const failed = RESULTS.filter((r) => r.rc !== 0)
const noExit = RESULTS.filter((r) => !r.exited)
console.log('')
console.log(`成员 ${RESULTS.length} 个；退出 0 的 ${RESULTS.length - failed.length} 个；`
  + `非 0 的 ${failed.length} 个${noExit.length ? `；没调 process.exit 的 ${noExit.length} 个` : ''}`)
if (failed.length) {
  for (const r of failed) console.log(`  FAIL 成员 ${r.name} → exit ${r.rc}`)
}
console.log(`结果：${failed.length ? '有失败成员' : 'ALL PASS'}（成员 ${RESULTS.length - failed.length}/${RESULTS.length}；`
  + `主题 ${THEME}）`)
process.exit(failed.length ? failed[0].rc : 0)
